UPDATE exercises SET muscles_primary = 'upper-back', muscles_secondary = 'biceps,forearm', instructions_en = '1. Hang from a pull-up bar with your palms facing away from you and your arms fully extended.
2. Engage your core and squeeze your shoulder blades together.
3. Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.
4. Pause at the top of the movement, then slowly lower your body back down to the starting position.
5. Repeat for the desired number of repetitions.', source_id = '0652' WHERE id = 'ex_wide_pull_up';
UPDATE exercises SET muscles_primary = 'chest', muscles_secondary = 'triceps,deltoids,abs', instructions_en = '1. Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.
2. Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.
3. Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.
4. Repeat for the desired number of repetitions.', source_id = '0662' WHERE id = 'ex_push_up';
UPDATE exercises SET muscles_primary = 'abs', muscles_secondary = 'obliques', instructions_en = '1. Sit on the ground with your knees bent and feet flat on the floor.
2. Lean back slightly while keeping your back straight and your core engaged.
3. Hold your hands together in front of your chest or hold a weight if desired.
4. Lift your feet off the ground, balancing on your sit bones.
5. Twist your torso to the right, bringing your hands or weight towards the right side of your body.
6. Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.
7. Continue alternating sides for the desired number of repetitions.', source_id = '0687' WHERE id = 'ex_russian_twist';

INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0001', '3/4 sit-up', '3/4 sit-up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors, lower back', '', '', 'abs', 'hip-flexors,lower-back', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0001');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0002', '45° side bend', '45° side bend', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques', '', '', 'abs', 'obliques', '1. Stand with your feet shoulder-width apart and your arms extended straight down by your sides.
2. Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.
3. Pause for a moment at the bottom, then slowly return to the starting position.
4. Repeat on the other side.
5. Continue alternating sides for the desired number of repetitions.', '0002');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1512', 'All fours squad stretch', 'All fours squad stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'quads', 'hamstrings, glutes', '', '', 'quadriceps', 'hamstring,gluteal', '1. Start on all fours with your hands directly under your shoulders and your knees directly under your hips.
2. Extend one leg straight back, keeping your knee bent and your foot flexed.
3. Slowly lower your hips towards the ground, feeling a stretch in your quads.
4. Hold this position for 20-30 seconds.
5. Switch legs and repeat the stretch on the other side.', '1512');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0006', 'Alternate heel touchers', 'Alternate heel touchers', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques', '', '', 'abs', 'obliques', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Extend your arms straight out to the sides, parallel to the ground.
3. Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.
4. Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.
5. Continue alternating sides for the desired number of repetitions.', '0006');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0007', 'Alternate lateral pulldown', 'Alternate lateral pulldown', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'lats', 'biceps, rhomboids', '', '', 'upper-back', 'biceps', '1. Sit on the cable machine with your back straight and feet flat on the ground.
2. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
3. Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.
4. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.
5. Repeat for the desired number of repetitions.', '0007');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1368', 'Ankle circles', 'Ankle circles', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'calves', 'ankle stabilizers', '', '', 'calves', '', '1. Sit on the ground with your legs extended in front of you.
2. Lift one leg off the ground and rotate your ankle in a circular motion.
3. Perform the desired number of circles in one direction, then switch to the other direction.
4. Repeat with the other leg.', '1368');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3293', 'Archer pull up', 'Archer pull up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.
2. Engage your core and pull your shoulder blades down and back.
3. As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.
4. Continue pulling until your chin is above the bar and your bent arm is fully flexed.
5. Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.
6. Alternate sides with each repetition.', '3293');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3294', 'Archer push up', 'Archer push up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Start in a push-up position with your hands slightly wider than shoulder-width apart.
2. Extend one arm straight out to the side, parallel to the ground.
3. Lower your body by bending your elbows, keeping your back straight and core engaged.
4. Push back up to the starting position.
5. Repeat on the other side, extending the opposite arm out to the side.
6. Continue alternating sides for the desired number of repetitions.', '3294');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2355', 'Arm slingers hanging bent knee legs', 'Arm slingers hanging bent knee legs', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'shoulders, back', '', '', 'abs', 'deltoids,upper-back', '1. Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.
2. Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.
3. Slowly lower your legs back down to the starting position.
4. Repeat for the desired number of repetitions.', '2355');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2333', 'Arm slingers hanging straight legs', 'Arm slingers hanging straight legs', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'shoulders, back', '', '', 'abs', 'deltoids,upper-back', '1. Hang from a pull-up bar with your arms fully extended and your legs straight down.
2. Engage your core and lift your legs up in front of you until they are parallel to the ground.
3. Hold for a moment at the top, then slowly lower your legs back down to the starting position.
4. Repeat for the desired number of repetitions.', '2333');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3214', 'Arms apart circular toe touch (male)', 'Arms apart circular toe touch (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings, quadriceps, calves', '', '', 'gluteal', 'hamstring,quadriceps,calves', '1. Stand with your feet shoulder-width apart and arms extended to the sides.
2. Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.
3. As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.
4. Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.
5. Continue alternating sides for the desired number of repetitions.', '3214');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3204', 'Arms overhead full sit-up (male)', 'Arms overhead full sit-up (male)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors, lower back', '', '', 'abs', 'hip-flexors,lower-back', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Extend your arms overhead, keeping them straight.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '3204');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0009', 'Assisted chest dip (kneeling)', 'Assisted chest dip (kneeling)', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Adjust the machine to your desired height and secure your knees on the pad.
2. Grasp the handles with your palms facing down and your arms fully extended.
3. Lower your body by bending your elbows until your upper arms are parallel to the floor.
4. Pause for a moment, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '0009');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0011', 'Assisted hanging knee raise', 'Assisted hanging knee raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.
3. Pause for a moment at the top of the movement, squeezing your abs.
4. Slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0011');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0010', 'Assisted hanging knee raise with throw down', 'Assisted hanging knee raise with throw down', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors, lower back', '', '', 'abs', 'hip-flexors,lower-back', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core and lift your knees towards your chest, keeping your legs together.
3. Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.
4. Allow your legs to swing back up and repeat the movement for the desired number of repetitions.', '0010');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1708', 'Assisted lying calves stretch', 'Assisted lying calves stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'calves', 'hamstrings', '', '', 'calves', 'hamstring', '1. Lie on your back with your legs extended.
2. Bend one knee and place your foot flat on the ground.
3. Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.
4. Hold the stretch for 20-30 seconds.
5. Release the stretch and repeat on the other leg.', '1708');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1709', 'Assisted lying glutes stretch', 'Assisted lying glutes stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings', '', '', 'gluteal', 'hamstring', '1. Lie on your back with your legs extended.
2. Bend your right knee and place your right ankle on your left thigh, just above the knee.
3. Grasp your left thigh with both hands and gently pull it towards your chest.
4. Hold the stretch for 20-30 seconds.
5. Release and repeat on the other side.', '1709');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1710', 'Assisted lying gluteus and piriformis stretch', 'Assisted lying gluteus and piriformis stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings', '', '', 'gluteal', 'hamstring', '1. Lie on your back with your legs extended.
2. Bend your right knee and place your right ankle on your left thigh, just above the knee.
3. Grasp your left thigh with both hands and gently pull it towards your chest.
4. Hold the stretch for 20-30 seconds.
5. Release the stretch and repeat on the other side.', '1710');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0012', 'Assisted lying leg raise with lateral throw down', 'Assisted lying leg raise with lateral throw down', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors, obliques', '', '', 'abs', 'hip-flexors,obliques', '1. Lie flat on your back with your legs extended and your arms by your sides.
2. Place your hands under your glutes for support.
3. Engage your abs and lift your legs off the ground, keeping them straight.
4. While keeping your legs together, lower them to one side until they are a few inches above the ground.
5. Pause for a moment, then lift your legs back to the starting position.
6. Repeat the movement to the other side.
7. Continue alternating sides for the desired number of repetitions.', '0012');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0013', 'Assisted lying leg raise with throw down', 'Assisted lying leg raise with throw down', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors, quadriceps', '', '', 'abs', 'hip-flexors,quadriceps', '1. Lie flat on your back with your legs extended and your arms by your sides.
2. Place your hands under your glutes for support.
3. Engage your core and lift your legs off the ground, keeping them straight.
4. Raise your legs until they are perpendicular to the ground.
5. Lower your legs back down to the starting position.
6. Simultaneously, throw your legs down towards the ground, keeping them straight.
7. Raise your legs back up to the starting position.
8. Repeat for the desired number of repetitions.', '0013');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0014', 'Assisted motion russian twist', 'Assisted motion russian twist', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'abs', 'obliques, lower back', '', '', 'abs', 'obliques,lower-back', '1. Sit on the ground with your knees bent and feet flat on the floor.
2. Hold the medicine ball with both hands in front of your chest.
3. Lean back slightly, engaging your abs and keeping your back straight.
4. Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.
5. Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.
6. Continue alternating sides for the desired number of repetitions.', '0014');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0015', 'Assisted parallel close grip pull-up', 'Assisted parallel close grip pull-up', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Adjust the machine to your desired weight and height.
2. Place your hands on the parallel bars with a close grip, palms facing each other.
3. Hang from the bars with your arms fully extended and your feet off the ground.
4. Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.
5. Continue pulling until your chin is above the bars.
6. Pause for a moment at the top, then slowly lower your body back down to the starting position.
7. Repeat for the desired number of repetitions.', '0015');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0016', 'Assisted prone hamstring', 'Assisted prone hamstring', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'hamstrings', 'glutes, lower back', '', '', 'hamstring', 'gluteal,lower-back', '1. Lie face down on a mat or bench with your legs fully extended.
2. Have a partner or use a resistance band to secure your ankles.
3. Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0016');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1713', 'Assisted prone lying quads stretch', 'Assisted prone lying quads stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'quads', 'hamstrings, glutes', '', '', 'quadriceps', 'hamstring,gluteal', '1. Lie face down on the ground with your legs extended.
2. Bend your left knee and reach back with your left hand to grab your left foot or ankle.
3. Gently pull your left foot towards your glutes, feeling a stretch in your left quad.
4. Hold the stretch for 20-30 seconds, then release.
5. Repeat with your right leg.', '1713');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1714', 'Assisted prone rectus femoris stretch', 'Assisted prone rectus femoris stretch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'quadriceps', '', '', 'abs', 'quadriceps', '1. Lie face down on the ground with your legs straight.
