INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0017', 'Assisted pull-up', 'Assisted pull-up', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Adjust the machine to your desired weight and height settings.
2. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
3. Hang with your arms fully extended and your feet off the ground.
4. Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.
