INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1413', 'Cable reverse one arm curl', 'Cable reverse one arm curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand facing a cable machine with your feet shoulder-width apart.
