INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0209', 'Cable reverse preacher curl', 'Cable reverse preacher curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Adjust the cable machine so that the preacher curl pad is at chest height.
2. Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.
3. Grab the cable handles with an underhand grip, shoulder-width apart.
