INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0207', 'Cable reverse-grip pushdown', 'Cable reverse-grip pushdown', 'arms', 'بازو', 'cable', 'سیم‌کش', 'triceps', 'forearms', '', '', 'triceps', 'forearm', '1. Attach a straight bar to a high pulley cable machine.
2. Stand facing the machine with your feet shoulder-width apart.
