INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0208', 'Cable reverse-grip straight back seated high row', 'Cable reverse-grip straight back seated high row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'upper back', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Sit on the seat facing the cable machine with your feet flat on the floor.
2. Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.
