INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1320', 'Cable rope crossover seated row', 'Cable rope crossover seated row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'upper back', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.
2. Grasp the cable ropes with an overhand grip, palms facing each other.
3. Lean back slightly, keeping your back straight and your core engaged.
4. Pull the cable ropes towards your chest, squeezing your shoulder blades together.
