INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1321', 'Cable rope elevated seated row', 'Cable rope elevated seated row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'upper back', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Sit on the elevated seat facing the cable machine.
2. Grab the cable rope handles with an overhand grip, palms facing each other.
3. Keep your back straight and lean slightly back, maintaining a slight bend in your knees.
