INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1656', 'Dumbbell biceps curl v sit on bosu ball', 'Dumbbell biceps curl v sit on bosu ball', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms, shoulders', '', '', 'biceps', 'forearm,deltoids', '1. Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.
3. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
4. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly begin to lower the dumbbells back to the starting position.
7. Repeat for the desired number of repetitions.', '1656');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0295', 'Dumbbell clean', 'Dumbbell clean', 'legs', 'پا', 'dumbbell', 'دمبل', 'glutes', 'hamstrings, quadriceps, calves', '', '', 'gluteal', 'hamstring,quadriceps,calves', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.
2. Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.
3. Explosively extend your hips and knees, driving through your heels to jump off the ground.
4. As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.
5. Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.
6. Lower the dumbbells back down to the starting position by reversing the movement.
7. Repeat for the desired number of repetitions.', '0295');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1731', 'Dumbbell close grip press', 'Dumbbell close grip press', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Sit on a flat bench with a dumbbell in each hand, resting on your thighs.
2. Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.
3. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.
4. As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.
5. As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.
6. After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.', '1731');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0296', 'Dumbbell close-grip press', 'Dumbbell close-grip press', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Sit on a flat bench with a dumbbell in each hand, resting on your thighs.
2. Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.
3. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.
4. As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.
5. As you exhale, use your triceps to lift the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '0296');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0297', 'Dumbbell concentration curl', 'Dumbbell concentration curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.
2. Fully extend your arm and hold the dumbbell with an underhand grip.
3. Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.
4. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly lower the dumbbell back to the starting position.
7. Repeat for the desired number of repetitions, then switch arms.', '0297');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3635', 'Dumbbell contralateral forward lunge', 'Dumbbell contralateral forward lunge', 'legs', 'پا', 'dumbbell', 'دمبل', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand.
2. Take a step forward with your right foot, keeping your back straight and core engaged.
3. Lower your body by bending both knees until your right thigh is parallel to the ground.
4. Push through your right heel to return to the starting position.
5. Repeat with your left leg.
6. Alternate legs for the desired number of repetitions.', '3635');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0298', 'Dumbbell cross body hammer curl', 'Dumbbell cross body hammer curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand up straight with a dumbbell in each hand, palms facing your body.
