INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0299', 'Dumbbell cuban press', 'Dumbbell cuban press', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.
2. Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.
3. Rotate your wrists so that your palms are facing forward.
4. Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.
5. Repeat for the desired number of repetitions.', '0299');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2136', 'Dumbbell cuban press v. 2', 'Dumbbell cuban press v. 2', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.
2. Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.
3. Rotate your wrists so that your palms are facing forward.
4. Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.
5. Repeat for the desired number of repetitions.', '2136');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0300', 'Dumbbell deadlift', 'Dumbbell deadlift', 'legs', 'پا', 'dumbbell', 'دمبل', 'glutes', 'hamstrings, lower back', '', '', 'gluteal', 'hamstring,lower-back', '1. Stand with your feet shoulder-width apart, toes pointing forward.
2. Hold a dumbbell in each hand, palms facing your body, arms extended downwards.
3. Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.
4. Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.
5. Repeat for the desired number of repetitions.', '0300');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0301', 'Dumbbell decline bench press', 'Dumbbell decline bench press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Lie down on a decline bench with your feet secured and your head lower than your hips.
2. Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.
3. Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.
4. Push the dumbbells back up to the starting position, fully extending your arms.
5. Repeat for the desired number of repetitions.', '0301');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0302', 'Dumbbell decline fly', 'Dumbbell decline fly', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders', '', '', 'chest', 'deltoids', '1. Lie on a decline bench with your feet secured and your head lower than your hips.
2. Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.
3. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.
4. Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.
5. Repeat for the desired number of repetitions.', '0302');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0303', 'Dumbbell decline hammer press', 'Dumbbell decline hammer press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Lie on a decline bench with your feet secured and your head lower than your hips.
2. Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.
3. Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.
4. Press the dumbbells back up to the starting position, fully extending your arms.
5. Repeat for the desired number of repetitions.', '0303');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1276', 'Dumbbell decline one arm fly', 'Dumbbell decline one arm fly', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders', '', '', 'chest', 'deltoids', '1. Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.
2. Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.
3. Rotate your wrist so that the palm of your hand is facing forward.
4. As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.
5. Exhale and use your chest muscles to bring the dumbbell back up to the starting position.
6. Repeat for the desired number of repetitions, then switch arms.', '1276');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1617', 'Dumbbell decline one arm hammer press', 'Dumbbell decline one arm hammer press', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Lie on a decline bench with a dumbbell in one hand, resting on your chest.
2. Extend your arm straight up, keeping your elbow slightly bent.
3. Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.
4. Press the dumbbell back up to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '1617');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0305', 'Dumbbell decline shrug', 'Dumbbell decline shrug', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'traps', 'shoulders, rhomboids', '', '', 'trapezius', 'deltoids,upper-back', '1. Set up a decline bench at a 45-degree angle.
2. Lie face down on the bench with your chest and stomach resting against it.
3. Hold a dumbbell in each hand with your arms fully extended towards the floor.
4. Keeping your arms straight, raise your shoulders towards your ears as high as possible.
5. Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '0305');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0304', 'Dumbbell decline shrug v. 2', 'Dumbbell decline shrug v. 2', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'traps', 'shoulders, rhomboids', '', '', 'trapezius', 'deltoids,upper-back', '1. Set up a decline bench at a 45-degree angle.
2. Lie face down on the bench with your chest and stomach resting on it.
3. Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.
4. Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.
5. Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '0304');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0306', 'Dumbbell decline triceps extension', 'Dumbbell decline triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.
2. Extend your arms fully, keeping your elbows close to your head.
3. Lower the dumbbells slowly behind your head, bending your elbows.
4. Pause for a moment, then raise the dumbbells back to the starting position.
5. Repeat for the desired number of repetitions.', '0306');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0307', 'Dumbbell decline twist fly', 'Dumbbell decline twist fly', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Lie down on a decline bench with your head lower than your hips.
2. Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.
3. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.
4. As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.
5. Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.
6. Repeat for the desired number of repetitions.', '0307');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1437', 'Dumbbell finger curls', 'Dumbbell finger curls', 'arms', 'بازو', 'dumbbell', 'دمبل', 'forearms', 'wrist flexors, wrist extensors', '', '', 'forearm', '', '1. Sit on a bench or chair with your feet flat on the ground and your back straight.
2. Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.
3. Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.
4. Repeat for the desired number of repetitions, then switch to the other hand.', '1437');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1277', 'Dumbbell fly on exercise ball', 'Dumbbell fly on exercise ball', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Sit on an exercise ball and hold a dumbbell in each hand.
2. Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.
3. Extend your arms straight up above your chest, palms facing each other.
4. Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.
5. Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '1277');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1732', 'Dumbbell forward lunge triceps extension', 'Dumbbell forward lunge triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders, core', '', '', 'triceps', 'deltoids,abs', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand.
2. Take a step forward with your right foot, lowering your body into a lunge position.
3. Keep your back straight and your chest up.
4. Extend your arms straight overhead, keeping your elbows close to your ears.
5. Lower the dumbbells behind your head by bending your elbows.
6. Pause for a moment, then straighten your arms to return to the starting position.
7. Repeat the movement for the desired number of repetitions, then switch legs and repeat.', '1732');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0309', 'Dumbbell front raise v. 2', 'Dumbbell front raise v. 2', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'trapezius, biceps', '', '', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.
2. Keep your back straight and engage your core.
3. Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.
4. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.
5. Repeat for the desired number of repetitions.', '0309');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0311', 'Dumbbell full can lateral raise', 'Dumbbell full can lateral raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'traps, rotator cuff', '', '', 'deltoids', 'trapezius', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.
2. Keep your back straight and engage your core.
3. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.
4. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
5. Repeat for the desired number of repetitions.', '0311');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1760', 'Dumbbell goblet squat', 'Dumbbell goblet squat', 'legs', 'پا', 'dumbbell', 'دمبل', 'quads', 'glutes, hamstrings, calves', '', '', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.
2. Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.
3. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
4. Pause for a moment at the bottom, then push through your heels to return to the starting position.
5. Repeat for the desired number of repetitions.', '1760');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1659', 'Dumbbell hammer curl on exercise ball', 'Dumbbell hammer curl on exercise ball', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on an exercise ball with your feet flat on the ground and your back straight.
2. Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.
3. Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.
4. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly begin to lower the dumbbells back to the starting position.
7. Repeat for the desired number of repetitions.', '1659');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0312', 'Dumbbell hammer curl v. 2', 'Dumbbell hammer curl v. 2', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand up straight with a dumbbell in each hand, palms facing your torso.
2. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.
3. This will be your starting position.
4. Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.
5. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.
6. Hold the contracted position for a brief pause as you squeeze your biceps.
7. Then, inhale and slowly begin to lower the dumbbells back to the starting position.
8. Repeat for the recommended amount of repetitions.', '0312');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2402', 'Dumbbell hammer curls (with arm blaster)', 'Dumbbell hammer curls (with arm blaster)', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand up straight with a dumbbell in each hand, palms facing your torso.
2. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.
3. This will be your starting position.
4. Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.
5. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.
6. Hold the contracted position for a brief pause as you squeeze your biceps.
7. Then, inhale and slowly begin to lower the dumbbells back to the starting position.
8. Repeat for the recommended amount of repetitions.', '2402');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1664', 'Dumbbell high curl', 'Dumbbell high curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand up straight with a dumbbell in each hand, palms facing forward.
2. Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.
3. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.
4. Repeat for the desired number of repetitions.', '1664');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3545', 'Dumbbell incline alternate press', 'Dumbbell incline alternate press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Sit on an incline bench with a dumbbell in each hand, resting on your thighs.
2. Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.
3. Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.
4. Push the dumbbells up with your chest and shoulders, extending your arms fully.
5. Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.
6. Repeat for the desired number of repetitions, alternating arms.', '3545');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0316', 'Dumbbell incline breeding', 'Dumbbell incline breeding', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Set up an incline bench at a 45-degree angle.
2. Sit on the bench with your back against the pad and feet flat on the ground.
3. Hold a dumbbell in each hand with an overhand grip, palms facing forward.
4. Start with your arms fully extended, perpendicular to the ground.
5. Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.
6. Pause for a moment at the bottom, then push the dumbbells back up to the starting position.
7. Repeat for the desired number of repetitions.', '0316');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0318', 'Dumbbell incline curl', 'Dumbbell incline curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.
2. Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms.
3. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
4. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly begin to lower the dumbbells back to the starting position.
7. Repeat for the desired number of repetitions.', '0318');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0317', 'Dumbbell incline curl v. 2', 'Dumbbell incline curl v. 2', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.
2. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
3. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
4. Hold the contracted position for a brief pause as you squeeze your biceps.
5. Inhale and slowly begin to lower the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '0317');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1278', 'Dumbbell incline fly on exercise ball', 'Dumbbell incline fly on exercise ball', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders', '', '', 'chest', 'deltoids', '1. Set up an incline bench at a 45-degree angle.
2. Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.
3. Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.
4. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.
5. Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '1278');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0320', 'Dumbbell incline hammer curl', 'Dumbbell incline hammer curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.
2. Keep your back against the bench and your feet flat on the floor.
3. While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
4. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly begin to lower the dumbbells back to the starting position.
7. Repeat for the desired number of repetitions.', '0320');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0321', 'Dumbbell incline hammer press', 'Dumbbell incline hammer press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.
2. Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.
3. Press the dumbbells up and away from your body until your arms are fully extended.
4. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.
5. Repeat for the desired number of repetitions.', '0321');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1618', 'Dumbbell incline hammer press on exercise ball', 'Dumbbell incline hammer press on exercise ball', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Sit on an exercise ball with a dumbbell in each hand, palms facing each other.
2. Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.
3. Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.
4. Press the dumbbells up and slightly inward, keeping your palms facing each other.
5. Extend your arms fully, squeezing your triceps at the top of the movement.
6. Slowly lower the dumbbells back to the starting position.
7. Repeat for the desired number of repetitions.', '1618');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0322', 'Dumbbell incline inner biceps curl', 'Dumbbell incline inner biceps curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on an incline bench with a dumbbell in each hand, palms facing each other.
2. Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.
3. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
4. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly begin to lower the dumbbells back to the starting position.
7. Repeat for the desired number of repetitions.', '0322');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1279', 'Dumbbell incline one arm fly', 'Dumbbell incline one arm fly', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'deltoids, triceps', '', '', 'chest', 'deltoids,triceps', '1. Adjust the incline bench to a 30-45 degree angle.
2. Sit on the bench with a dumbbell in one hand, resting it on your thigh.
3. Lie back on the bench, keeping your feet flat on the ground.
4. Hold the dumbbell with your arm extended straight up over your chest.
5. Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.
6. Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.
7. Repeat for the desired number of repetitions, then switch arms.', '1279');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1280', 'Dumbbell incline one arm fly on exercise ball', 'Dumbbell incline one arm fly on exercise ball', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders', '', '', 'chest', 'deltoids', '1. Sit on an exercise ball with a dumbbell in one hand.
2. Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.
3. Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.
4. Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.
5. Pause for a moment when your arm is parallel to the ground.
6. Engage your chest muscles to bring the dumbbell back up to the starting position.
7. Repeat for the desired number of repetitions, then switch arms.', '1280');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1619', 'Dumbbell incline one arm hammer press', 'Dumbbell incline one arm hammer press', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders, chest', '', '', 'triceps', 'deltoids,chest', '1. Sit on an incline bench with a dumbbell in one hand, resting on your thigh.
2. Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.
3. Rotate your wrist so that your palm is facing inward, towards your body.
4. Press the dumbbell up and away from your body, extending your arm fully.
5. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.
6. Repeat for the desired number of repetitions, then switch arms.', '1619');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1620', 'Dumbbell incline one arm hammer press on exercise ball', 'Dumbbell incline one arm hammer press on exercise ball', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders, chest', '', '', 'triceps', 'deltoids,chest', '1. Sit on an exercise ball with a dumbbell in one hand.
2. Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.
3. Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.
4. Press the dumbbell up towards the ceiling, straightening your arm.
5. Lower the dumbbell back down to the starting position.
6. Repeat for the desired number of repetitions, then switch arms.', '1620');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0323', 'Dumbbell incline one arm lateral raise', 'Dumbbell incline one arm lateral raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'trapezius, triceps', '', '', 'deltoids', 'trapezius,triceps', '1. Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.
2. Lean forward and position your upper arm against the inside of your thigh.
3. Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.
4. Continue lifting until your arm is parallel to the floor.
5. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.
6. Repeat for the desired number of repetitions, then switch to the other arm.', '0323');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1281', 'Dumbbell incline one arm press', 'Dumbbell incline one arm press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Sit on an incline bench with a dumbbell in one hand, resting on your thigh.
2. Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.
3. Press the dumbbell upward and slightly inward, extending your arm fully.
4. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.
5. Repeat for the desired number of repetitions, then switch to the other arm.', '1281');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1282', 'Dumbbell incline one arm press on exercise ball', 'Dumbbell incline one arm press on exercise ball', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.
2. Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.
3. Hold the dumbbell at shoulder height with your palm facing forward.
4. Press the dumbbell upward until your arm is fully extended.
5. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.
6. Repeat for the desired number of repetitions, then switch to the other arm.', '1282');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0324', 'Dumbbell incline palm-in press', 'Dumbbell incline palm-in press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Set up an incline bench at a 45-degree angle.
2. Sit on the bench with a dumbbell in each hand, palms facing each other.
3. Plant your feet firmly on the ground and keep your back straight against the bench.
4. Start with the dumbbells at shoulder level, elbows bent and palms facing each other.
5. Press the dumbbells up and away from your body, extending your arms fully.
6. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.
7. Repeat for the desired number of repetitions.', '0324');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1283', 'Dumbbell incline press on exercise ball', 'Dumbbell incline press on exercise ball', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Sit on an exercise ball with a dumbbell in each hand, palms facing forward.
2. Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.
3. Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.
4. Press the dumbbells upward, extending your arms fully.
5. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '1283');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0325', 'Dumbbell incline raise', 'Dumbbell incline raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'trapezius, triceps', '', '', 'deltoids', 'trapezius,triceps', '1. Sit on an incline bench with a dumbbell in each hand, resting on your thighs.
2. Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.
3. Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.
4. Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.
5. Repeat for the desired number of repetitions.', '0325');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0326', 'Dumbbell incline rear lateral raise', 'Dumbbell incline rear lateral raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'traps, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Set up an incline bench at a 45-degree angle.
2. Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.
3. Extend your arms straight down with your palms facing each other.
4. Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.
5. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
6. Repeat for the desired number of repetitions.', '0326');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0327', 'Dumbbell incline row', 'Dumbbell incline row', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'upper back', 'biceps, shoulders', '', '', 'upper-back', 'biceps,deltoids', '1. Set up an incline bench at a 45-degree angle.
2. Grab a dumbbell in each hand and sit on the bench with your chest against the incline.
3. Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders.
4. Pull the dumbbells up towards your chest, squeezing your shoulder blades together.
5. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '0327');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0328', 'Dumbbell incline shoulder raise', 'Dumbbell incline shoulder raise', 'chest', 'سینه', 'dumbbell', 'دمبل', 'serratus anterior', 'deltoids, trapezius', '', '', 'serratus', 'deltoids,trapezius', '1. Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.
2. Rest the dumbbells on your thighs and lean back onto the bench.
3. Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.
4. Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.
5. Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.
6. Repeat for the desired number of repetitions.', '0328');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0329', 'Dumbbell incline shrug', 'Dumbbell incline shrug', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'traps', 'shoulders', '', '', 'trapezius', 'deltoids', '1. Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.
2. Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.
3. Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.
4. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.
5. Repeat for the desired number of repetitions.', '0329');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3542', 'Dumbbell incline t-raise', 'Dumbbell incline t-raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'traps, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.
2. Lean forward and let your arms hang straight down, perpendicular to the floor.
3. Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a ''T'' shape with your body.
4. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
5. Repeat for the desired number of repetitions.', '3542');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0330', 'Dumbbell incline triceps extension', 'Dumbbell incline triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Sit on an incline bench with a dumbbell in each hand, palms facing inwards.
2. Extend your arms fully overhead, keeping your elbows close to your head.
3. Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.
4. Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.
5. Repeat for the desired number of repetitions.', '0330');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0331', 'Dumbbell incline twisted flyes', 'Dumbbell incline twisted flyes', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.
2. Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.
3. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.
4. As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.
5. Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.
6. Repeat for the desired number of repetitions.', '0331');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1733', 'Dumbbell incline two arm extension', 'Dumbbell incline two arm extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Sit on an incline bench with a dumbbell in each hand, resting on your thighs.
2. Slowly lie back on the bench, keeping the dumbbells close to your chest.
3. Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.
4. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.
5. Repeat for the desired number of repetitions.', '1733');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3541', 'Dumbbell incline y-raise', 'Dumbbell incline y-raise', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'upper back', 'shoulders, rear deltoids', '', '', 'upper-back', 'deltoids', '1. Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.
2. Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.
3. Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.
4. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
5. Repeat for the desired number of repetitions.', '3541');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0332', 'Dumbbell iron cross', 'Dumbbell iron cross', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'triceps, chest', '', '', 'deltoids', 'triceps,chest', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.
2. Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.
3. Pause for a moment, then slowly lower your arms back down to the starting position.
4. Repeat for the desired number of repetitions.', '0332');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0333', 'Dumbbell kickback', 'Dumbbell kickback', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.
4. Extend your arms straight back, squeezing your triceps at the top of the movement.
5. Pause for a moment, then slowly lower the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '0333');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1734', 'Dumbbell kickbacks on exercise ball', 'Dumbbell kickbacks on exercise ball', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders, back', '', '', 'triceps', 'deltoids,upper-back', '1. Sit on an exercise ball with your feet flat on the ground and your back straight.
2. Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.
3. Extend your arms straight back, squeezing your triceps at the top of the movement.
4. Pause for a moment, then slowly lower the dumbbells back to the starting position.
5. Repeat for the desired number of repetitions.', '1734');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1660', 'Dumbbell kneeling bicep curl exercise ball', 'Dumbbell kneeling bicep curl exercise ball', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Kneel on the floor with an exercise ball in front of you.
2. Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.
3. Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.
4. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly begin to lower the dumbbells back to the starting position.
7. Repeat for the desired number of repetitions.', '1660');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0335', 'Dumbbell lateral to front raise', 'Dumbbell lateral to front raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'trapezius, biceps', '', '', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.
2. Keep your back straight and engage your core.
3. Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.
4. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
5. Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.
6. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
7. Repeat for the desired number of repetitions.', '0335');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0336', 'Dumbbell lunge', 'Dumbbell lunge', 'legs', 'پا', 'dumbbell', 'دمبل', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand.
2. Take a step forward with your right foot, lowering your body into a lunge position.
3. Keep your back straight and your chest up as you lower your body.
4. Push through your right heel to return to the starting position.
5. Repeat with your left leg.
6. Alternate legs for the desired number of repetitions.', '0336');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1658', 'Dumbbell lunge with bicep curl', 'Dumbbell lunge with bicep curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'quadriceps, hamstrings', '', '', 'biceps', 'quadriceps,hamstring', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.
2. Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.
3. As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.
4. Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.
5. Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.
6. Continue alternating sides for the desired number of repetitions.', '1658');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0337', 'Dumbbell lying extension (across face)', 'Dumbbell lying extension (across face)', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.
2. Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.
3. Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.
4. Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.
5. Repeat for the desired number of repetitions.', '0337');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1729', 'Dumbbell lying alternate extension', 'Dumbbell lying alternate extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Lie flat on a bench with a dumbbell in each hand, palms facing each other.
2. Extend your arms straight up over your chest, keeping a slight bend in your elbows.
3. Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.
4. Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.
5. Repeat with the other arm, alternating sides for the desired number of repetitions.', '1729');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0338', 'Dumbbell lying elbow press', 'Dumbbell lying elbow press', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.
2. Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.
3. Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.
4. Repeat for the desired number of repetitions.', '0338');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0863', 'Dumbbell lying external shoulder rotation', 'Dumbbell lying external shoulder rotation', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'rotator cuff, triceps', '', '', 'deltoids', 'triceps', '1. Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.
2. Hold a dumbbell in your hand with your palm facing down.
3. Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.
4. Pause for a moment at the top, then slowly lower your forearm back down to the starting position.
5. Repeat for the desired number of repetitions, then switch sides.', '0863');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0339', 'Dumbbell lying femoral', 'Dumbbell lying femoral', 'legs', 'پا', 'dumbbell', 'دمبل', 'hamstrings', 'glutes', '', '', 'hamstring', 'gluteal', '1. Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.
2. Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.
3. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.
4. Repeat for the desired number of repetitions.', '0339');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0340', 'Dumbbell lying hammer press', 'Dumbbell lying hammer press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.
2. Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.
3. Press the dumbbells back up to the starting position, fully extending your arms.
4. Repeat for the desired number of repetitions.', '0340');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2470', 'Dumbbell lying on floor rear delt raise', 'Dumbbell lying on floor rear delt raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'trapezius, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Lie face down on the floor with a dumbbell in each hand, palms facing each other.
2. Extend your arms straight out in front of you, keeping a slight bend in your elbows.
3. Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.
4. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
5. Repeat for the desired number of repetitions.', '2470');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0341', 'Dumbbell lying one arm deltoid rear', 'Dumbbell lying one arm deltoid rear', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'trapezius, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.
2. Extend your arm straight down towards the floor, keeping it close to your body.
3. Raise your arm up and back, squeezing your shoulder blade towards your spine.
4. Pause for a moment at the top, then slowly lower your arm back down to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '0341');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0343', 'Dumbbell lying one arm press', 'Dumbbell lying one arm press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.
2. Hold the dumbbell at shoulder level with your palm facing forward.
3. Press the dumbbell upward until your arm is fully extended.
4. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.
5. Repeat for the desired number of repetitions, then switch to the other arm.', '0343');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0342', 'Dumbbell lying one arm press v. 2', 'Dumbbell lying one arm press v. 2', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Lie flat on a bench with your back supported and feet flat on the ground.
2. Hold a dumbbell in one hand with your palm facing towards your feet.
3. Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.
4. Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.
5. Pause for a moment at the bottom, then push the dumbbell back up to the starting position.
6. Repeat for the desired number of repetitions, then switch to the other arm.', '0342');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0344', 'Dumbbell lying one arm pronated triceps extension', 'Dumbbell lying one arm pronated triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Lie flat on a bench with your back and head supported, and your feet flat on the ground.
2. Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.
3. Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.
4. Pause for a moment at the bottom, then extend your arm back up to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '0344');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0345', 'Dumbbell lying one arm rear lateral raise', 'Dumbbell lying one arm rear lateral raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'traps, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.
2. Keep your arm straight and lift the dumbbell out to the side, away from your body.
3. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.
4. Repeat for the desired number of repetitions, then switch to the other arm.', '0345');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0346', 'Dumbbell lying one arm supinated triceps extension', 'Dumbbell lying one arm supinated triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'forearms', '', '', 'triceps', 'forearm', '1. Lie flat on a bench with your back and head supported, and your feet flat on the ground.
2. Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.
3. Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.
4. Pause for a moment at the bottom, then extend your arm back up to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '0346');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0347', 'Dumbbell lying pronation', 'Dumbbell lying pronation', 'arms', 'بازو', 'dumbbell', 'دمبل', 'forearms', 'biceps, shoulders', '', '', 'forearm', 'biceps,deltoids', '1. Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.
2. Rotate your palms so they are facing up.
3. Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.
4. Inhale and slowly lower the dumbbells back to the starting position.
5. Repeat for the desired number of repetitions.', '0347');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2705', 'Dumbbell lying pronation on floor', 'Dumbbell lying pronation on floor', 'arms', 'بازو', 'dumbbell', 'دمبل', 'forearms', 'biceps, triceps', '', '', 'forearm', 'biceps,triceps', '1. Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.
2. Rotate your palms so they are facing down towards the floor.
3. Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.
4. Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.
5. Hold for a moment, then slowly lower the dumbbells back down to the starting position.
6. Repeat for the desired number of repetitions.', '2705');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1284', 'Dumbbell lying pullover on exercise ball', 'Dumbbell lying pullover on exercise ball', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'triceps, shoulders, back', '', '', 'chest', 'triceps,deltoids,upper-back', '1. Sit on an exercise ball and roll forward until your upper back is resting on the ball.
2. Hold a dumbbell with both hands and extend your arms straight up over your chest.
3. Slowly lower the dumbbell behind your head while keeping your arms straight.
4. Pause for a moment, then raise the dumbbell back to the starting position.
5. Repeat for the desired number of repetitions.', '1284');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1328', 'Dumbbell lying rear delt row', 'Dumbbell lying rear delt row', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'upper back', 'shoulders, biceps', '', '', 'upper-back', 'deltoids,biceps', '1. Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.
2. Extend your arms straight down towards the floor, keeping a slight bend in your elbows.
3. Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.
4. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.
5. Repeat for the desired number of repetitions.', '1328');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0348', 'Dumbbell lying rear lateral raise', 'Dumbbell lying rear lateral raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'traps, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.
