INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1735', 'Dumbbell lying single extension', 'Dumbbell lying single extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.
