INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0352', 'Dumbbell neutral grip bench press', 'Dumbbell neutral grip bench press', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.
3. Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.
4. Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.
5. Repeat for the desired number of repetitions.', '0352');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1285', 'Dumbbell one arm bench fly', 'Dumbbell one arm bench fly', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders', '', '', 'chest', 'deltoids', '1. Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.
2. Lie back on the bench, keeping the dumbbell pressed against your thigh.
3. Using your free hand, help lift the dumbbell up to the starting position.
4. Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.
5. Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.
6. Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.
7. Repeat for the desired number of repetitions, then switch arms and repeat.', '1285');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1286', 'Dumbbell one arm chest fly on exercise ball', 'Dumbbell one arm chest fly on exercise ball', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.
2. Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.
3. Extend your arm with the dumbbell straight up above your chest, palm facing inward.
4. Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.
5. Pause for a moment when your arm is parallel to the ground.
6. Engage your chest muscles to bring the dumbbell back up to the starting position.
7. Repeat for the desired number of repetitions, then switch arms.', '1286');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0353', 'Dumbbell one arm concentration curl (on stability ball)', 'Dumbbell one arm concentration curl (on stability ball)', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.
3. Rest your elbow on the inside of your thigh, just above the knee.
4. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.
5. Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.
6. Repeat for the desired number of repetitions, then switch arms and repeat.', '0353');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1287', 'Dumbbell one arm decline chest press', 'Dumbbell one arm decline chest press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Lie on a decline bench with a dumbbell in one hand, resting on your chest.
2. Place your feet flat on the ground and keep your back pressed against the bench.
3. Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.
4. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.
5. Repeat for the desired number of repetitions, then switch to the other arm.', '1287');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1288', 'Dumbbell one arm fly on exercise ball', 'Dumbbell one arm fly on exercise ball', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.
2. Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.
3. Extend your arm with the dumbbell straight up above your chest, palm facing inwards.
4. Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.
5. Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.
6. Repeat for the desired number of repetitions, then switch arms.', '1288');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1736', 'Dumbbell one arm french press on exercise ball', 'Dumbbell one arm french press on exercise ball', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Sit on an exercise ball with your feet flat on the ground and your back straight.
2. Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.
3. Extend your arm straight up towards the ceiling, keeping your elbow stationary.
4. Slowly lower the dumbbell back down to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '1736');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1663', 'Dumbbell one arm hammer preacher curl', 'Dumbbell one arm hammer preacher curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.
