INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1621', 'Dumbbell one arm hammer press on exercise ball', 'Dumbbell one arm hammer press on exercise ball', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders, chest', '', '', 'triceps', 'deltoids,chest', '1. Sit on an exercise ball with your feet flat on the ground and your back straight.
