INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1289', 'Dumbbell one arm incline chest press', 'Dumbbell one arm incline chest press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Adjust the incline bench to a 45-degree angle.
