INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1329', 'Dumbbell palm rotational bent over row', 'Dumbbell palm rotational bent over row', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'upper back', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.
2. Bend forward at the hips, keeping your back straight and your knees slightly bent.
3. Let your arms hang straight down, palms facing your body.
4. Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.
5. As you pull the dumbbells up, rotate your palms so they face away from your body.
6. Squeeze your shoulder blades together at the top of the movement.
7. Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.
8. Repeat for the desired number of repetitions.', '1329');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1623', 'Dumbbell palms in incline bench press', 'Dumbbell palms in incline bench press', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Set up an incline bench at a 45-degree angle.
2. Sit on the bench with your back against the backrest and feet flat on the ground.
3. Hold a dumbbell in each hand with an overhand grip, palms facing inwards.
4. Extend your arms straight up above your chest, keeping a slight bend in your elbows.
5. Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.
6. Pause for a moment at the bottom, then press the dumbbells back up to the starting position.
7. Repeat for the desired number of repetitions.', '1623');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0370', 'Dumbbell peacher hammer curl', 'Dumbbell peacher hammer curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand up straight with a dumbbell in each hand, palms facing your torso.
2. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.
3. This will be your starting position.
4. Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.
5. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.
6. Hold the contracted position for a brief pause as you squeeze your biceps.
7. Then, inhale and slowly begin to lower the dumbbells back to the starting position.
8. Repeat for the recommended amount of repetitions.', '0370');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0371', 'Dumbbell plyo squat', 'Dumbbell plyo squat', 'legs', 'پا', 'dumbbell', 'دمبل', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.
2. Lower your body into a squat position by bending your knees and pushing your hips back.
3. As you reach the bottom of the squat, explode upward, jumping off the ground.
4. While in the air, quickly switch the position of your feet, landing with your opposite foot forward.
5. Immediately lower your body back into a squat position and repeat the jump, switching your feet again.
6. Continue alternating the position of your feet with each jump for the desired number of repetitions.', '0371');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0372', 'Dumbbell preacher curl', 'Dumbbell preacher curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.
2. Hold a dumbbell in each hand with your palms facing up and your arms fully extended.
3. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
4. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly begin to lower the dumbbells back to the starting position.
7. Repeat for the desired number of repetitions.', '0372');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1673', 'Dumbbell preacher curl over exercise ball', 'Dumbbell preacher curl over exercise ball', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on an exercise ball with your feet flat on the ground and your back straight.
2. Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.
3. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.
4. Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '1673');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1293', 'Dumbbell press on exercise ball', 'Dumbbell press on exercise ball', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.
2. Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.
3. Raise the dumbbells to shoulder height, palms facing forward.
4. Press the dumbbells upward until your arms are fully extended.
5. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '1293');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0373', 'Dumbbell pronate-grip triceps extension', 'Dumbbell pronate-grip triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'forearms', '', '', 'triceps', 'forearm', '1. Sit on a bench or chair with your back straight and feet flat on the ground.
2. Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.
3. Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.
4. Pause for a moment, then extend your arms back up to the starting position.
5. Repeat for the desired number of repetitions.', '0373');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0374', 'Dumbbell prone incline curl', 'Dumbbell prone incline curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Adjust the bench to a 45-degree incline.
2. Lie face down on the bench with your chest and stomach resting against it.
3. Hold a dumbbell in each hand with your palms facing down and your arms fully extended.
4. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
5. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.
6. Hold the contracted position for a brief pause as you squeeze your biceps.
7. Inhale and slowly begin to lower the dumbbells back to the starting position.
8. Repeat for the desired number of repetitions.', '0374');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1674', 'Dumbbell prone incline hammer curl', 'Dumbbell prone incline hammer curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Adjust the bench to a 45-degree incline.
2. Lie face down on the bench with a dumbbell in each hand, palms facing each other.
3. Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.
4. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
5. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
6. Hold the contracted position for a brief pause as you squeeze your biceps.
7. Inhale and slowly begin to lower the dumbbells back to the starting position.
8. Repeat for the desired number of repetitions.', '1674');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0375', 'Dumbbell pullover', 'Dumbbell pullover', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'latissimus dorsi, triceps', '', '', 'chest', 'upper-back,triceps', '1. Lie flat on a bench with your head at one end and your feet on the floor.
2. Hold a dumbbell with both hands and extend your arms straight above your chest.
3. Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.
4. Pause for a moment, then raise the dumbbell back to the starting position.
5. Repeat for the desired number of repetitions.', '0375');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1294', 'Dumbbell pullover hip extension on exercise ball', 'Dumbbell pullover hip extension on exercise ball', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.
2. Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.
3. Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.
4. Lower the dumbbell behind your head, keeping your arms straight and maintaining control.
5. Pause for a moment, then raise the dumbbell back to the starting position.
6. While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.
7. Lower your hips back down to the starting position.
8. Repeat for the desired number of repetitions.', '1294');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1295', 'Dumbbell pullover on exercise ball', 'Dumbbell pullover on exercise ball', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'triceps, latissimus dorsi', '', '', 'chest', 'triceps,upper-back', '1. Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.
2. Slowly lower the dumbbell behind your head while keeping your arms straight.
3. Pause for a moment, then raise the dumbbell back to the starting position.
4. Repeat for the desired number of repetitions.', '1295');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1700', 'Dumbbell push press', 'Dumbbell push press', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'triceps, core', '', '', 'deltoids', 'triceps,abs', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.
