INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0381', 'Dumbbell rear lunge', 'Dumbbell rear lunge', 'legs', 'پا', 'dumbbell', 'دمبل', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand.
2. Take a step backward with your right foot, lowering your body into a lunge position.
3. Bend your left knee and lower your body until your left thigh is parallel to the ground.
4. Pause for a moment, then push through your left heel to return to the starting position.
5. Repeat on the other side, stepping back with your left foot.', '0381');
