INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1624', 'Dumbbell reverse bench press', 'Dumbbell reverse bench press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your knees bent.
2. Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.
3. Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.
