INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1459', 'Dumbbell romanian deadlift', 'Dumbbell romanian deadlift', 'legs', 'پا', 'dumbbell', 'دمبل', 'glutes', 'hamstrings, lower back', '', '', 'gluteal', 'hamstring,lower-back', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.
2. Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.
3. Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.
4. Repeat for the desired number of repetitions.', '1459');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0386', 'Dumbbell rotation reverse fly', 'Dumbbell rotation reverse fly', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'trapezius, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.
3. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.
4. Rotate your arms so that your palms are facing downwards.
5. Slowly lower your arms back to the starting position.
6. Repeat for the desired number of repetitions.', '0386');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2397', 'Dumbbell scott press', 'Dumbbell scott press', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'triceps, chest', '', '', 'deltoids', 'triceps,chest', '1. Sit on a bench with a dumbbell in each hand, palms facing forward.
2. Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.
3. Press the dumbbells upward until your arms are fully extended.
4. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.
5. Repeat for the desired number of repetitions.', '2397');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0387', 'Dumbbell seated alternate front raise', 'Dumbbell seated alternate front raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'trapezius, biceps', '', '', 'deltoids', 'trapezius,biceps', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.
3. Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.
4. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.
5. Repeat with the other arm.
6. Alternate between arms for the desired number of repetitions.', '0387');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1676', 'Dumbbell seated alternate hammer curl on exercise ball', 'Dumbbell seated alternate hammer curl on exercise ball', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on an exercise ball with your feet flat on the ground and your back straight.
2. Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.
3. Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.
4. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly lower the dumbbell back to the starting position.
7. Repeat the movement with the opposite arm.
8. Continue alternating arms for the desired number of repetitions.', '1676');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0388', 'Dumbbell seated alternate press', 'Dumbbell seated alternate press', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'triceps, chest', '', '', 'deltoids', 'triceps,chest', '1. Sit on a bench with a dumbbell in each hand, palms facing forward.
2. Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.
3. Press one dumbbell up overhead, fully extending your arm.
4. Lower the dumbbell back down to shoulder height.
5. Repeat with the other arm.
6. Continue alternating arms for the desired number of repetitions.', '0388');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3546', 'Dumbbell seated alternate shoulder', 'Dumbbell seated alternate shoulder', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.
3. Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.
4. Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.
5. Continue alternating between arms for the desired number of repetitions.', '3546');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0389', 'Dumbbell seated bench extension', 'Dumbbell seated bench extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a dumbbell with both hands and extend your arms straight up above your head.
3. Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.
4. Pause for a moment, then raise the dumbbell back up to the starting position.
5. Repeat for the desired number of repetitions.', '0389');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2317', 'Dumbbell seated bent arm lateral raise', 'Dumbbell seated bent arm lateral raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'trapezius, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.
3. Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.
4. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
5. Repeat for the desired number of repetitions.', '2317');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1730', 'Dumbbell seated bent over alternate kickback', 'Dumbbell seated bent over alternate kickback', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders, back', '', '', 'triceps', 'deltoids,upper-back', '1. Sit on a bench with a dumbbell in each hand, palms facing inwards.
2. Bend forward at the waist, keeping your back straight and parallel to the ground.
3. Extend one arm straight back, keeping it close to your body, until your arm is fully extended.
4. Pause for a moment, then slowly lower the dumbbell back to the starting position.
5. Repeat with the other arm.
6. Continue alternating arms for the desired number of repetitions.', '1730');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1737', 'Dumbbell seated bent over triceps extension', 'Dumbbell seated bent over triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders, back', '', '', 'triceps', 'deltoids,upper-back', '1. Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.
2. Bend forward at the waist, keeping your back straight and your head up.
3. Extend your arms straight back, keeping your elbows close to your head.
4. Pause for a moment, then slowly lower the dumbbells back to the starting position.
5. Repeat for the desired number of repetitions.', '1737');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1677', 'Dumbbell seated bicep curl', 'Dumbbell seated bicep curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.
2. Keep your back straight and your elbows close to your torso.
3. Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.
4. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.
5. Repeat for the desired number of repetitions.', '1677');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0390', 'Dumbbell seated biceps curl (on stability ball)', 'Dumbbell seated biceps curl (on stability ball)', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a stability ball with your feet flat on the ground and your back straight.
2. Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.
3. Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.
4. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly begin to lower the dumbbells back to the starting position.
7. Repeat for the desired number of repetitions.', '0390');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3547', 'Dumbbell seated biceps curl to shoulder press', 'Dumbbell seated biceps curl to shoulder press', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'shoulders', '', '', 'biceps', 'deltoids', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a dumbbell in each hand with your palms facing forward and arms fully extended.
3. Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.
4. Once your forearms are vertical, rotate your wrists so that your palms are facing forward.
5. Press the dumbbells overhead until your arms are fully extended.
6. Lower the dumbbells back down to the starting position by reversing the movement.
7. Repeat for the desired number of repetitions.', '3547');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1379', 'Dumbbell seated calf raise', 'Dumbbell seated calf raise', 'legs', 'پا', 'dumbbell', 'دمبل', 'calves', 'hamstrings', '', '', 'calves', 'hamstring', '1. Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.
2. Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.
3. Hold onto the dumbbell for stability.
4. Raise your heels as high as possible, lifting your body weight onto the balls of your feet.
5. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '1379');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0391', 'Dumbbell seated curl', 'Dumbbell seated curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.
