INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1678', 'Dumbbell seated hammer curl', 'Dumbbell seated hammer curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.
