INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0397', 'Dumbbell seated neutral wrist curl', 'Dumbbell seated neutral wrist curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.
2. Rest your forearms on your thighs, allowing the dumbbells to hang down.
3. Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.
4. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.
5. Repeat for the desired number of repetitions.', '0397');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1679', 'Dumbbell seated one arm bicep curl on exercise ball with leg raised', 'Dumbbell seated one arm bicep curl on exercise ball with leg raised', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms, shoulders', '', '', 'biceps', 'forearm,deltoids', '1. Sit on an exercise ball with your feet flat on the ground and your back straight.
2. Hold a dumbbell in one hand with your palm facing up and your arm fully extended.
3. Place your other hand on your hip for stability.
4. Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.
5. Pause for a moment at the top of the movement, squeezing your bicep.
6. Slowly lower the dumbbell back to the starting position.
7. Repeat for the desired number of repetitions.
8. Switch arms and repeat the exercise.', '1679');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0398', 'Dumbbell seated one arm kickback', 'Dumbbell seated one arm kickback', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.
2. Bend your torso forward at the waist, keeping your back straight and parallel to the ground.
3. Extend your arm straight back, keeping your elbow close to your body.
4. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '0398');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0399', 'Dumbbell seated one arm rotate', 'Dumbbell seated one arm rotate', 'arms', 'بازو', 'dumbbell', 'دمبل', 'forearms', 'shoulders, biceps', '', '', 'forearm', 'deltoids,biceps', '1. Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.
2. Raise the dumbbell up to shoulder height, keeping your elbow close to your body.
3. Rotate your forearm outward, away from your body, while keeping your upper arm stationary.
4. Pause for a moment at the top, then slowly rotate your forearm back to the starting position.
5. Repeat for the desired number of repetitions, then switch to the other arm.', '0399');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0400', 'Dumbbell seated one leg calf raise', 'Dumbbell seated one leg calf raise', 'legs', 'پا', 'dumbbell', 'دمبل', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.
2. Extend your left leg straight out in front of you, keeping your foot flexed.
3. Place the ball of your right foot on an elevated surface, such as a step or weight plate.
4. Using your calf muscles, raise your right heel as high as possible.
5. Pause for a moment at the top, then slowly lower your heel back down to the starting position.
6. Repeat for the desired number of repetitions, then switch legs.', '0400');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1380', 'Dumbbell seated one leg calf raise - hammer grip', 'Dumbbell seated one leg calf raise - hammer grip', 'legs', 'پا', 'dumbbell', 'دمبل', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.
2. Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.
3. Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.
4. Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.
5. Pause for a moment at the top, then slowly lower your heel back down to the starting position.
6. Repeat for the desired number of repetitions, then switch to the other leg.', '1380');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1381', 'Dumbbell seated one leg calf raise - palm up', 'Dumbbell seated one leg calf raise - palm up', 'legs', 'پا', 'dumbbell', 'دمبل', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Sit on a bench or chair with your back straight and your feet flat on the ground.
2. Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.
3. Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.
4. Raise your heel as high as possible by pushing through the ball of your foot.
5. Pause for a moment at the top, then slowly lower your heel back down.
6. Repeat for the desired number of repetitions, then switch legs and repeat.', '1381');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0401', 'Dumbbell seated palms up wrist curl', 'Dumbbell seated palms up wrist curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'forearms', 'biceps, shoulders', '', '', 'forearm', 'biceps,deltoids', '1. Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.
2. Rest your forearms on your thighs, allowing your wrists to hang off the edge.
3. Slowly curl your wrists upward, squeezing your forearms at the top of the movement.
4. Pause for a moment, then lower your wrists back down to the starting position.
5. Repeat for the desired number of repetitions.', '0401');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0402', 'Dumbbell seated preacher curl', 'Dumbbell seated preacher curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a preacher curl bench with your feet flat on the floor.
2. Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.
3. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.
4. Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '0402');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0403', 'Dumbbell seated revers grip concentration curl', 'Dumbbell seated revers grip concentration curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.
2. Rest your elbow on the inside of your thigh, just above the knee.
3. Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.
4. Pause for a moment at the top, squeezing your biceps.
5. Inhale and slowly lower the dumbbell back to the starting position.
6. Repeat for the desired number of repetitions, then switch arms.', '0403');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1738', 'Dumbbell seated reverse grip one arm overhead tricep extension', 'Dumbbell seated reverse grip one arm overhead tricep extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a dumbbell with an underhand grip and extend your arm straight up overhead.
3. Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.
4. Pause for a moment, then extend your arm back up to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '1738');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0404', 'Dumbbell seated shoulder press (parallel grip)', 'Dumbbell seated shoulder press (parallel grip)', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Sit on a bench with a dumbbell in each hand, palms facing inward.
2. Raise the dumbbells to shoulder height, elbows bent and palms facing forward.
3. Press the dumbbells upward until your arms are fully extended overhead.
4. Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.
5. Repeat for the desired number of repetitions.', '0404');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2188', 'Dumbbell seated triceps extension', 'Dumbbell seated triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a dumbbell with both hands and extend your arms straight up overhead.
3. Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.
4. Pause for a moment, then straighten your arms and return to the starting position.
5. Repeat for the desired number of repetitions.', '2188');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0406', 'Dumbbell shrug', 'Dumbbell shrug', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'traps', 'shoulders', '', '', 'trapezius', 'deltoids', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.
2. Keep your arms straight and let the dumbbells hang by your sides.
3. Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders.
4. Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.
5. Repeat for the desired number of repetitions.', '0406');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0407', 'Dumbbell side bend', 'Dumbbell side bend', 'core', 'شکم و میان‌تنه', 'dumbbell', 'دمبل', 'abs', 'obliques', '', '', 'abs', 'obliques', '1. Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.
2. Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.
3. Pause for a moment, then slowly return to the starting position.
4. Repeat for the desired number of repetitions, then switch sides and repeat.', '0407');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0408', 'Dumbbell side lying one hand raise', 'Dumbbell side lying one hand raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'trapezius, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Lie on your side with your legs extended and your head supported by your arm.
2. Hold a dumbbell in your top hand with your palm facing down.
3. Keeping your arm straight, raise the dumbbell up to shoulder height.
4. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.
5. Repeat for the desired number of repetitions, then switch sides.', '0408');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3664', 'Dumbbell side plank with rear fly', 'Dumbbell side plank with rear fly', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'upper back', 'shoulders, core', '', '', 'upper-back', 'deltoids,abs', '1. Start by lying on your side with your legs extended and stacked on top of each other.
2. Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.
3. Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.
4. Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.
5. While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.
6. Lower the dumbbell back down to the starting position.
7. Repeat for the desired number of repetitions, then switch sides.', '3664');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3548', 'Dumbbell single arm overhead carry', 'Dumbbell single arm overhead carry', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'traps, core', '', '', 'deltoids', 'trapezius,abs', '1. Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.
2. Raise the dumbbell overhead, fully extending your arm.
3. Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.
4. Continue walking for the desired distance or time.
5. Switch hands and repeat the exercise.', '3548');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0409', 'Dumbbell single leg calf raise', 'Dumbbell single leg calf raise', 'legs', 'پا', 'dumbbell', 'دمبل', 'calves', 'ankles', '', '', 'calves', '', '1. Stand on the edge of a step or platform with your heels hanging off and your toes on the step.
2. Hold a dumbbell in one hand and place your other hand on a wall or railing for support.
3. Raise your heel as high as possible, lifting your body up onto your toes.
4. Pause for a moment at the top, then slowly lower your heel back down below the step.
5. Repeat for the desired number of repetitions, then switch to the other leg.', '0409');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1757', 'Dumbbell single leg deadlift', 'Dumbbell single leg deadlift', 'legs', 'پا', 'dumbbell', 'دمبل', 'glutes', 'hamstrings, lower back', '', '', 'gluteal', 'hamstring,lower-back', '1. Stand with your feet hip-width apart, holding a dumbbell in your right hand.
2. Shift your weight onto your left leg and lift your right foot slightly off the ground.
3. Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.
4. At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.
5. Lower the dumbbell until your torso and right leg are parallel to the ground.
6. Pause for a moment, then engage your glutes and hamstrings to return to the starting position.
7. Repeat for the desired number of repetitions, then switch sides.', '1757');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2805', 'Dumbbell single leg deadlift with stepbox support', 'Dumbbell single leg deadlift with stepbox support', 'legs', 'پا', 'dumbbell', 'دمبل', 'glutes', 'hamstrings, lower back', '', '', 'gluteal', 'hamstring,lower-back', '1. Stand with your feet hip-width apart, holding a dumbbell in your right hand.
2. Place your left foot on a stepbox or elevated surface behind you.
3. Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.
4. As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.
5. Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.
6. Repeat for the desired number of repetitions, then switch sides.', '2805');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0410', 'Dumbbell single leg split squat', 'Dumbbell single leg split squat', 'legs', 'پا', 'dumbbell', 'دمبل', 'quads', 'glutes, hamstrings, calves', '', '', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand.
2. Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.
3. Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.
4. Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.
5. Repeat for the desired number of repetitions, then switch legs and repeat.', '0410');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0411', 'Dumbbell single leg squat', 'Dumbbell single leg squat', 'legs', 'پا', 'dumbbell', 'دمبل', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand.
2. Extend one leg forward and keep it off the ground throughout the exercise.
3. Bend your standing leg and lower your body down as if sitting back into a chair.
4. Keep your chest up and your back straight.
5. Pause for a moment at the bottom, then push through your heel to return to the starting position.
6. Repeat for the desired number of repetitions, then switch legs.', '0411');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0413', 'Dumbbell squat', 'Dumbbell squat', 'legs', 'پا', 'dumbbell', 'دمبل', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.
2. Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.
3. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
4. Pause for a moment at the bottom, then push through your heels to return to the starting position.
5. Repeat for the desired number of repetitions.', '0413');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3560', 'Dumbbell standing alternate hammer curl and press', 'Dumbbell standing alternate hammer curl and press', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms, shoulders', '', '', 'biceps', 'forearm,deltoids', '1. Stand up straight with a dumbbell in each hand, palms facing your body.
2. Keep your elbows close to your torso and your back straight.
3. Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.
4. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.
5. Inhale and slowly lower the dumbbell back to the starting position.
6. Repeat the curl with your left hand.
7. After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.
8. Extend your arm fully and hold for a moment at the top.
9. Inhale and slowly lower the dumbbell back to the starting position.
10. Repeat the press with your left hand.
11. Continue alternating between curls and presses for the desired number of repetitions.', '3560');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0414', 'Dumbbell standing alternate overhead press', 'Dumbbell standing alternate overhead press', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'triceps, core', '', '', 'deltoids', 'triceps,abs', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.
2. Press one dumbbell overhead, fully extending your arm.
3. Lower the dumbbell back to shoulder level.
4. Repeat with the other arm.
5. Continue alternating arms for the desired number of repetitions.', '0414');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0415', 'Dumbbell standing alternate raise', 'Dumbbell standing alternate raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'traps, forearms', '', '', 'deltoids', 'trapezius,forearm', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.
2. Keep your back straight and your core engaged.
3. Raise one dumbbell to the side, keeping your arm straight and your palm facing down.
4. Continue lifting until your arm is parallel to the ground.
5. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.
6. Repeat with the other arm.
7. Alternate between arms for the desired number of repetitions.', '0415');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1739', 'Dumbbell standing alternating tricep kickback', 'Dumbbell standing alternating tricep kickback', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Extend your arms straight back, keeping your elbows close to your body.
4. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.
5. Repeat with the other arm, alternating sides with each repetition.', '1739');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2143', 'Dumbbell standing around world', 'Dumbbell standing around world', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'triceps, forearms', '', '', 'deltoids', 'triceps,forearm', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand.
2. Extend your arms straight out to the sides at shoulder height, palms facing down.
3. Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.
4. Continue the circular motion, bringing the dumbbells back down to the starting position.
5. Repeat for the desired number of repetitions.', '2143');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1740', 'Dumbbell standing bent over one arm triceps extension', 'Dumbbell standing bent over one arm triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders, back', '', '', 'triceps', 'deltoids,upper-back', '1. Stand with your feet shoulder-width apart and hold a dumbbell in one hand.
2. Bend forward at the waist, keeping your back straight and parallel to the ground.
3. Extend your arm straight back, keeping your elbow close to your body.
4. Slowly lower the dumbbell back to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '1740');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1741', 'Dumbbell standing bent over two arm triceps extension', 'Dumbbell standing bent over two arm triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders, back', '', '', 'triceps', 'deltoids,upper-back', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand.
2. Bend forward at the waist, keeping your back straight and your knees slightly bent.
3. Extend your arms straight back, keeping your elbows close to your body.
4. Slowly lower the dumbbells back down to the starting position.
5. Repeat for the desired number of repetitions.', '1741');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0416', 'Dumbbell standing biceps curl', 'Dumbbell standing biceps curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.
2. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
3. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
4. Hold the contracted position for a brief pause as you squeeze your biceps.
5. Inhale and slowly begin to lower the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '0416');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0417', 'Dumbbell standing calf raise', 'Dumbbell standing calf raise', 'legs', 'پا', 'dumbbell', 'دمبل', 'calves', 'ankles', '', '', 'calves', '', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand.
2. Raise your heels off the ground as high as possible, using your calves.
3. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
4. Repeat for the desired number of repetitions.', '0417');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0418', 'Dumbbell standing concentration curl', 'Dumbbell standing concentration curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.
2. Place your opposite hand on your thigh for support.
3. Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.
4. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly lower the dumbbell back to the starting position.
7. Repeat for the desired number of repetitions, then switch arms.', '0418');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0419', 'Dumbbell standing front raise above head', 'Dumbbell standing front raise above head', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'delts', 'trapezius, biceps', '', '', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.
2. Keep your arms straight and lift the dumbbells in front of you, raising them above your head.
3. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.
4. Repeat for the desired number of repetitions.', '0419');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2321', 'Dumbbell standing inner biceps curl v. 2', 'Dumbbell standing inner biceps curl v. 2', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand up straight with a dumbbell in each hand, palms facing your torso.
2. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.
3. While holding your upper arms stationary, curl the weights while contracting your biceps.
4. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Slowly begin to bring the dumbbells back to the starting position as your breathe in.
7. Repeat for the recommended amount of repetitions.', '2321');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0420', 'Dumbbell standing kickback', 'Dumbbell standing kickback', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Extend your arms straight back, squeezing your triceps at the top of the movement.
4. Pause for a moment, then slowly lower the dumbbells back to the starting position.
5. Repeat for the desired number of repetitions.', '0420');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0421', 'Dumbbell standing one arm concentration curl', 'Dumbbell standing one arm concentration curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.
2. Place your free hand on your thigh for support.
3. Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.
4. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly lower the dumbbell back to the starting position.
7. Repeat for the desired number of repetitions, then switch arms.', '0421');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0422', 'Dumbbell standing one arm curl (over incline bench)', 'Dumbbell standing one arm curl (over incline bench)', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.
2. Place your other hand on an incline bench for support.
