INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1680', 'Dumbbell standing one arm curl over incline bench', 'Dumbbell standing one arm curl over incline bench', 'arms', 'بازو', 'dumbbell', 'دمبل', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand with your feet shoulder-width apart, holding a dumbbell in one hand.
2. Place your other hand on an incline bench for support.
