INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0593', 'Lever reverse hyperextension', 'Lever reverse hyperextension', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'hamstrings, lower back', '', '', 'gluteal', 'hamstring,lower-back', '1. Adjust the leverage machine to fit your body and secure your feet in the foot pads.
2. Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.
3. Cross your arms over your chest or place them behind your head.
4. Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.
5. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
6. Repeat for the desired number of repetitions.', '0593');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2315', 'Lever rotary calf', 'Lever rotary calf', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'soleus, ankle stabilizers', '', '', 'calves', '', '1. Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.
2. Place your toes on the footplate, with your heels hanging off the edge.
3. Grasp the handles or the sides of the machine for stability.
4. Push through the balls of your feet, raising your heels as high as possible.
5. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '2315');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2335', 'Lever seated calf press', 'Lever seated calf press', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'soleus, hamstrings', '', '', 'calves', 'hamstring', '1. Adjust the seat of the machine so that your shoulders are aligned with the lever pad.
2. Place your toes on the lower portion of the platform and position your knees under the lever pad.
3. Grasp the handles on the sides of the seat for stability.
4. Press the lever pad down by extending your ankles, lifting your heels as high as possible.
5. Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '2335');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0594', 'Lever seated calf raise', 'Lever seated calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'soleus, ankle stabilizers', '', '', 'calves', '', '1. Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.
2. Place your toes on the footplate with your heels hanging off the edge.
3. Grasp the handles or the sides of the seat for stability.
4. Push through the balls of your feet to raise your heels as high as possible.
5. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '0594');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1452', 'Lever seated crunch', 'Lever seated crunch', 'core', 'شکم و میان‌تنه', 'machine', 'دستگاه', 'abs', 'obliques', '', '', 'abs', 'obliques', '1. Sit on the leverage machine with your back against the pad and your feet flat on the floor.
2. Grasp the handles or place your hands on the side pads for support.
3. Engage your abs and slowly lean back, allowing the pad to move with you.
4. Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.
5. Pause for a moment at the top, then slowly release and return to the starting position.
6. Repeat for the desired number of repetitions.', '1452');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0595', 'Lever seated crunch (chest pad)', 'Lever seated crunch (chest pad)', 'core', 'شکم و میان‌تنه', 'machine', 'دستگاه', 'abs', 'obliques', '', '', 'abs', 'obliques', '1. Adjust the seat height and chest pad position according to your comfort.
2. Sit on the machine with your back against the chest pad and your feet flat on the floor.
3. Grasp the handles or side bars for stability.
4. Engage your abs and slowly lean back, allowing the chest pad to move with you.
5. Pause for a moment at the maximum contraction, feeling the tension in your abs.
6. Slowly return to the starting position by contracting your abs and pulling yourself back up.
7. Repeat for the desired number of repetitions.', '0595');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3760', 'Lever seated crunch v. 2', 'Lever seated crunch v. 2', 'core', 'شکم و میان‌تنه', 'machine', 'دستگاه', 'abs', 'obliques, hip flexors', '', '', 'abs', 'obliques,hip-flexors', '1. Sit on the leverage machine with your back against the pad and your feet secured under the footpads.
2. Place your hands on the handles or the sides of the seat for support.
3. Engage your abs and slowly crunch forward, bringing your chest towards your knees.
4. Pause for a moment at the top of the movement, squeezing your abs.
5. Slowly return to the starting position, allowing your back to round slightly.
6. Repeat for the desired number of repetitions.', '3760');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1451', 'Lever seated dip', 'Lever seated dip', 'arms', 'بازو', 'machine', 'دستگاه', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.
2. Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.
3. Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.
4. Pause for a moment, then push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '1451');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0596', 'Lever seated fly', 'Lever seated fly', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'deltoids, trapezius', '', '', 'chest', 'deltoids,trapezius', '1. Adjust the seat height and position yourself on the machine with your back against the pad.
2. Grasp the handles with a pronated grip and keep your elbows slightly bent.
3. Exhale and push the handles forward, bringing them together in front of your chest.
4. Pause for a moment, squeezing your chest muscles.
5. Inhale and slowly return to the starting position, allowing your chest muscles to stretch.
6. Repeat for the desired number of repetitions.', '0596');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3759', 'Lever seated good morning', 'Lever seated good morning', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'hamstrings, lower back', '', '', 'gluteal', 'hamstring,lower-back', '1. Adjust the seat height so that your hips are slightly higher than your knees.
2. Sit on the machine with your back against the pad and your feet flat on the footrests.
3. Grasp the handles or the sides of the seat for stability.
4. Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.
5. Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.
6. Repeat for the desired number of repetitions.', '3759');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0597', 'Lever seated hip abduction', 'Lever seated hip abduction', 'legs', 'پا', 'machine', 'دستگاه', 'abductors', 'glutes, hamstrings', '', '', 'gluteal', 'hamstring', '1. Adjust the seat height so that your knees are at a 90-degree angle.
2. Sit on the machine with your back against the backrest and your feet on the footrests.
3. Place your hands on the side handles for stability.
4. Engage your abductors and slowly push your legs apart, away from the midline of your body.
5. Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.
6. Repeat for the desired number of repetitions.', '0597');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0598', 'Lever seated hip adduction', 'Lever seated hip adduction', 'legs', 'پا', 'machine', 'دستگاه', 'adductors', 'hamstrings, glutes', '', '', 'adductors', 'hamstring,gluteal', '1. Adjust the seat height and position yourself on the machine with your back against the backrest.
2. Place your feet on the footrests and grasp the handles for stability.
3. Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.
4. Pause for a moment at the peak contraction, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '0598');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0600', 'Lever seated leg raise crunch', 'Lever seated leg raise crunch', 'core', 'شکم و میان‌تنه', 'machine', 'دستگاه', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Sit on the leverage machine with your back against the backrest and your feet on the footrests.
2. Grasp the handles or sidebars for stability.
3. Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.
4. Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.
5. Repeat for the desired number of repetitions.', '0600');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0602', 'Lever seated reverse fly', 'Lever seated reverse fly', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'trapezius, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.
2. Grasp the handles with an overhand grip and keep your arms slightly bent.
3. Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.
4. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '0602');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0601', 'Lever seated reverse fly (parallel grip)', 'Lever seated reverse fly (parallel grip)', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'trapezius, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.
2. Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.
3. Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.
4. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '0601');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1350', 'Lever seated row', 'Lever seated row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'upper back', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Adjust the seat height and footrests to a comfortable position.
2. Sit on the machine with your chest against the pad and your feet on the footrests.
3. Grasp the handles with an overhand grip, shoulder-width apart.
4. Keep your back straight and your core engaged.
5. Pull the handles towards your body, squeezing your shoulder blades together.
6. Pause for a moment at the peak of the movement.
7. Slowly release the handles and return to the starting position.
8. Repeat for the desired number of repetitions.', '1350');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1385', 'Lever seated squat calf raise on leg press machine', 'Lever seated squat calf raise on leg press machine', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'quadriceps, hamstrings, glutes', '', '', 'calves', 'quadriceps,hamstring,gluteal', '1. Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.
2. Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.
3. Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.
4. Release the safety handles and push the footplate away from you by extending your knees.
5. Once your knees are fully extended, slowly lower your heels by flexing your calves.
6. Pause for a moment at the bottom, then push the footplate back up by extending your calves.
7. Repeat for the desired number of repetitions.', '1385');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0603', 'Lever shoulder press', 'Lever shoulder press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'triceps, chest', '', '', 'deltoids', 'triceps,chest', '1. Adjust the seat height and position yourself on the machine with your back against the backrest.
2. Grasp the handles with an overhand grip and position your hands at shoulder level.
3. Push the handles upward until your arms are fully extended, but do not lock your elbows.
4. Pause for a moment at the top, then slowly lower the handles back down to the starting position.
5. Repeat for the desired number of repetitions.', '0603');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0869', 'Lever shoulder press v. 2', 'Lever shoulder press v. 2', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'triceps, chest', '', '', 'deltoids', 'triceps,chest', '1. Adjust the seat height and backrest of the leverage machine to a comfortable position.
2. Sit on the machine with your back against the backrest and your feet flat on the floor.
3. Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.
4. Push the handles upward and forward until your arms are fully extended, but not locked.
5. Pause for a moment at the top, then slowly lower the handles back down to the starting position.
6. Repeat for the desired number of repetitions.', '0869');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2318', 'Lever shoulder press v. 3', 'Lever shoulder press v. 3', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'triceps, chest', '', '', 'deltoids', 'triceps,chest', '1. Adjust the seat height and backrest of the leverage machine to a comfortable position.
