INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0604', 'Lever shrug', 'Lever shrug', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'traps', 'shoulders', '', '', 'trapezius', 'deltoids', '1. Adjust the seat height and position yourself on the leverage machine with your back against the pad.
