INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3758', 'Lever standing chest press', 'Lever standing chest press', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Adjust the seat height and position yourself on the machine with your feet flat on the ground.
