INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1351', 'Lever t-bar reverse grip row', 'Lever t-bar reverse grip row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'upper back', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.
