INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0607', 'Lever triceps extension', 'Lever triceps extension', 'arms', 'بازو', 'machine', 'دستگاه', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Adjust the seat height and position yourself on the machine with your back against the pad.
