INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0609', 'London bridge', 'London bridge', 'back', 'پشت و زیربغل', 'other', 'سایر', 'upper back', 'shoulders, biceps, forearms', '', '', 'upper-back', 'deltoids,biceps,forearm', '1. Attach the rope to a high anchor point.
2. Stand facing away from the anchor point with your feet shoulder-width apart.
3. Grasp the rope with an overhand grip, palms facing down.
4. Lean forward slightly, keeping your back straight and core engaged.
5. Pull the rope towards your body, squeezing your shoulder blades together.
6. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.
7. Repeat for the desired number of repetitions.', '0609');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3013', 'Low glute bridge on floor', 'Low glute bridge on floor', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings, core', '', '', 'gluteal', 'hamstring,abs', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your arms by your sides, palms facing down.
3. Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.
4. Pause for a moment at the top, squeezing your glutes.
5. Slowly lower your hips back down to the starting position.
6. Repeat for the desired number of repetitions.', '3013');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1352', 'Lower back curl', 'Lower back curl', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'spine', 'glutes, hamstrings', '', '', 'lower-back', 'gluteal,hamstring', '1. Lie flat on your stomach with your legs extended and your arms by your sides.
2. Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.
3. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
4. Repeat for the desired number of repetitions.', '1352');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3582', 'Lunge with jump', 'Lunge with jump', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Start by standing with your feet shoulder-width apart.
2. Take a step forward with your right foot, lowering your body into a lunge position.
3. Push off with your right foot and jump into the air, switching the position of your feet mid-air.
4. Land softly with your left foot forward and immediately lower your body into a lunge position.
5. Continue alternating between lunges and jumps for the desired number of repetitions.', '3582');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1688', 'Lunge with twist', 'Lunge with twist', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'quadriceps, glutes, hamstrings', '', '', 'abs', 'quadriceps,gluteal,hamstring', '1. Start by standing with your feet shoulder-width apart.
2. Take a step forward with your right foot, lowering your body into a lunge position.
3. As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.
4. Pause for a moment, then return to the starting position.
5. Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.
6. Continue alternating sides for the desired number of repetitions.', '1688');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0613', 'Lying (side) quads stretch', 'Lying (side) quads stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'quads', 'hamstrings', '', '', 'quadriceps', 'hamstring', '1. Lie on your side with your legs straight.
2. Bend your top leg and grab your ankle or foot with your hand.
3. Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.
4. Hold the stretch for 20-30 seconds.
5. Release the stretch and repeat on the other side.', '0613');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2312', 'Lying elbow to knee', 'Lying elbow to knee', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors, lower back', '', '', 'abs', 'hip-flexors,lower-back', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.
4. At the same time, extend your right leg straight out and lift it off the ground.
5. Pause for a moment, then return to the starting position.
6. Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.
7. Continue alternating sides for the desired number of repetitions.', '2312');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0620', 'Lying leg raise flat bench', 'Lying leg raise flat bench', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Lie flat on a flat bench with your back pressed against it.
2. Place your hands under your glutes for support.
3. Keep your legs straight and together, and lift them up towards the ceiling.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0620');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0865', 'Lying leg-hip raise', 'Lying leg-hip raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Lie flat on your back with your legs extended and your arms by your sides.
2. Place your hands under your glutes for support.
3. Engage your core and lift your legs off the ground, raising them towards the ceiling.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0865');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1301', 'Machine inner chest press', 'Machine inner chest press', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Adjust the seat height and position yourself on the machine with your back flat against the pad.
2. Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.
3. Push the handles forward until your arms are fully extended, exhaling during the movement.
4. Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.
5. Repeat for the desired number of repetitions.', '1301');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0624', 'March sit (wall)', 'March sit (wall)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your back against a wall and your feet hip-width apart.
2. Slowly slide your back down the wall until your knees are bent at a 90-degree angle.
3. Lift your right foot off the ground and bring your knee towards your chest.
4. Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.
5. Continue alternating between lifting your right and left foot for the desired number of repetitions.', '0624');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1353', 'Medicine ball catch and overhead throw', 'Medicine ball catch and overhead throw', 'back', 'پشت و زیربغل', 'other', 'سایر', 'lats', 'shoulders, core', '', '', 'upper-back', 'deltoids,abs', '1. Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.
2. Bend your knees slightly and engage your core.
3. Lower your body into a squat position, keeping your back straight and chest up.
4. Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.
5. Release the ball at the top of the movement and catch it on the way down.
6. Lower your body back into the squat position and repeat for the desired number of repetitions.', '1353');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1302', 'Medicine ball chest pass', 'Medicine ball chest pass', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Stand with your feet shoulder-width apart, holding the medicine ball at chest level.
2. Extend your arms forward, pushing the medicine ball away from your chest with force.
3. As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.
4. Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.
5. Continue for the desired number of repetitions.', '1302');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1303', 'Medicine ball chest push from 3 point stance', 'Medicine ball chest push from 3 point stance', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.
2. Extend your legs and position your body in a straight line.
3. Lower your chest towards the ground while keeping your back straight.
4. Push the medicine ball away from your body, extending your arm fully.
5. Return to the starting position and repeat for the desired number of repetitions.', '1303');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1304', 'Medicine ball chest push multiple response', 'Medicine ball chest push multiple response', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Stand with your feet shoulder-width apart, holding a medicine ball at chest level.
2. Extend your arms forward, pushing the medicine ball away from your chest.
3. Pause for a moment, then slowly bring the medicine ball back to your chest.
4. Repeat for the desired number of repetitions.', '1304');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1305', 'Medicine ball chest push single response', 'Medicine ball chest push single response', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Stand with your feet shoulder-width apart, holding the medicine ball at chest level.
2. Extend your arms forward, pushing the medicine ball away from your chest.
3. Pause for a moment, then slowly bring the medicine ball back to your chest.
4. Repeat for the desired number of repetitions.', '1305');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1312', 'Medicine ball chest push with run release', 'Medicine ball chest push with run release', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Stand with your feet shoulder-width apart, holding a medicine ball at chest level.
2. Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.
3. As you push the ball forward, release it and let it roll forward.
4. Quickly run forward and catch the ball before it hits the ground.
5. Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.
6. Continue alternating legs and repeating the exercise for the desired number of repetitions.', '1312');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1701', 'Medicine ball close grip push up', 'Medicine ball close grip push up', 'arms', 'بازو', 'other', 'سایر', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Start in a high plank position with your hands on the medicine ball, shoulder-width apart.
2. Lower your body towards the ground by bending your elbows, keeping them close to your sides.
3. Push back up to the starting position, fully extending your arms.
4. Repeat for the desired number of repetitions.', '1701');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1354', 'Medicine ball overhead slam', 'Medicine ball overhead slam', 'back', 'پشت و زیربغل', 'other', 'سایر', 'upper back', 'shoulders, core', '', '', 'upper-back', 'deltoids,abs', '1. Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.
2. Engage your core and keep your back straight.
3. Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.
4. As you slam the ball down, use your entire body to generate power, including your shoulders and core.
5. Catch the ball on the bounce and repeat for the desired number of repetitions.', '1354');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1750', 'Medicine ball supine chest throw', 'Medicine ball supine chest throw', 'arms', 'بازو', 'other', 'سایر', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Lie flat on your back on a bench with your knees bent and feet flat on the ground.
2. Hold the medicine ball with both hands, extending your arms straight up above your chest.
3. Lower the medicine ball towards your chest, keeping your elbows close to your body.
4. Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.
5. Catch the medicine ball and repeat for the desired number of repetitions.', '1750');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0627', 'Mixed grip chin-up', 'Mixed grip chin-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.
2. Hang from the bar with your arms fully extended and your feet off the ground.
3. Engage your back muscles and pull your body up towards the bar, leading with your chest.
4. Continue pulling until your chin is above the bar.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position with control.
6. Repeat for the desired number of repetitions.', '0627');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3217', 'Modified hindu push-up (male)', 'Modified hindu push-up (male)', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.
2. Lower your body towards the ground, bending your elbows and keeping your core engaged.
3. As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.
4. Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.
5. Repeat for the desired number of repetitions.', '3217');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1421', 'Modified push up to lower arms', 'Modified push up to lower arms', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'forearms', 'triceps, chest, shoulders', '', '', 'forearm', 'triceps,chest,deltoids', '1. Start in a push-up position with your hands directly under your shoulders and your body in a straight line.
2. Lower your body down towards the ground by bending your elbows, keeping them close to your sides.
3. Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.
4. Pause for a moment, then push through your palms to lift your forearms back up to the starting position.
5. Repeat for the desired number of repetitions.', '1421');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0628', 'Monster walk', 'Monster walk', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings, quadriceps', '', '', 'gluteal', 'hamstring,quadriceps', '1. Place a resistance band around your ankles.
2. Stand with your feet shoulder-width apart and slightly bend your knees.
3. Take a step to the side with your right foot, maintaining tension on the resistance band.
4. Follow with your left foot, stepping to the side to return to the starting position.
5. Repeat for the desired number of repetitions, then switch sides.', '0628');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0631', 'Muscle up', 'Muscle up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, triceps, shoulders, chest', '', '', 'upper-back', 'biceps,triceps,deltoids,chest', '1. Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.
2. Engage your core and pull your body up towards the bar, leading with your chest.
3. As you reach the top of the movement, transition your grip so that your palms are facing towards you.
4. Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.
5. Reverse the movement by slowly lowering yourself back down to the starting position.
6. Repeat for the desired number of repetitions.', '0631');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1401', 'Muscle-up (on vertical bar)', 'Muscle-up (on vertical bar)', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, triceps, forearms', '', '', 'upper-back', 'biceps,triceps,forearm', '1. Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.
2. Engage your core and pull your body up towards the bar, leading with your chest.
3. As you pull yourself up, lean back slightly and bring your elbows towards your sides.
4. Continue pulling until your chest reaches the bar and your elbows are fully bent.
5. Pause for a moment at the top, then slowly lower yourself back down to the starting position.
6. Repeat for the desired number of repetitions.', '1401');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2328', 'Narrow push-up on exercise ball', 'Narrow push-up on exercise ball', 'arms', 'بازو', 'other', 'سایر', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.
2. Engage your core and keep your body in a straight line from head to toe.
3. Lower your chest towards the ball by bending your elbows, keeping them close to your body.
4. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '2328');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0634', 'Negative crunch', 'Negative crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0634');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1495', 'Oblique crunch v. 2', 'Oblique crunch v. 2', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques', '', '', 'abs', 'obliques', '1. Lie on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head or cross them over your chest.
3. Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.
4. Pause for a moment, then lower your shoulder blades back down to the starting position.
5. Repeat on the other side.
6. Continue alternating sides for the desired number of repetitions.', '1495');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0635', 'Oblique crunches floor', 'Oblique crunches floor', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques', '', '', 'abs', 'obliques', '1. Lie on your back with your knees bent and feet flat on the floor.
2. Place your hands behind your head or cross them over your chest.
3. Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.
4. Pause for a moment, then lower your shoulder blades back down to the floor.
5. Repeat on the other side, alternating sides with each repetition.', '0635');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0636', 'Olympic barbell hammer curl', 'Olympic barbell hammer curl', 'arms', 'بازو', 'barbell', 'هالتر', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.
2. Let the barbell hang at arm''s length in front of your thighs, with your palms facing your body.
3. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
4. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly begin to lower the barbell back to the starting position.
7. Repeat for the desired number of repetitions.', '0636');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0637', 'Olympic barbell triceps extension', 'Olympic barbell triceps extension', 'arms', 'بازو', 'barbell', 'هالتر', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.
2. Raise the barbell above your head, fully extending your arms.
3. Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.
4. Pause for a moment, then extend your arms back to the starting position.
5. Repeat for the desired number of repetitions.', '0637');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1355', 'One arm against wall', 'One arm against wall', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'shoulders, triceps', '', '', 'upper-back', 'deltoids,triceps', '1. Stand facing a wall with your feet shoulder-width apart.
2. Extend one arm straight out in front of you and place your palm against the wall.
3. Engage your core and lean your body forward, keeping your arm straight and your back flat.
4. Slowly push against the wall with your palm, activating your lat muscles.
5. Hold the position for a few seconds, then release and repeat with the other arm.', '1355');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0638', 'One arm chin-up', 'One arm chin-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Stand facing a pull-up bar with your feet shoulder-width apart.
2. Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.
3. Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.
4. Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.
5. Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.
6. Repeat for the desired number of repetitions, then switch arms and repeat.', '0638');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0639', 'One arm dip', 'One arm dip', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Stand facing away from a bench or chair, with your feet shoulder-width apart.
2. Place one hand on the bench or chair behind you, fingers pointing towards your body.
3. Extend your legs out in front of you, keeping your heels on the ground.
4. Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.
5. Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.
6. Repeat for the desired number of repetitions, then switch sides and repeat with the other arm.', '0639');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0640', 'One arm slam (with medicine ball)', 'One arm slam (with medicine ball)', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'abs', 'shoulders, back', '', '', 'abs', 'deltoids,upper-back', '1. Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.
2. Bend your knees slightly and engage your core.
3. Raise the medicine ball above your head, fully extending your arm.
4. Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.
5. Catch the medicine ball on the bounce and repeat for the desired number of repetitions.', '0640');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1773', 'One arm towel row', 'One arm towel row', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'upper back', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.
2. Bend forward at the waist, keeping your back straight and your core engaged.
3. Extend your arm fully, allowing the towel to hang in front of you.
4. Pull the towel towards your chest, squeezing your shoulder blades together.
5. Pause for a moment at the top, then slowly lower the towel back to the starting position.
6. Repeat for the desired number of repetitions, then switch arms.', '1773');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1386', 'One leg donkey calf raise', 'One leg donkey calf raise', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Stand with your feet shoulder-width apart, toes pointing forward.
2. Place your hands on a stable surface for support, such as a wall or a bar.
3. Lift one leg off the ground, keeping your knee slightly bent.
4. Raise your heel as high as possible, using your calf muscles.
5. Pause for a moment at the top, then slowly lower your heel back down.
6. Repeat for the desired number of repetitions, then switch legs.', '1386');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1387', 'One leg floor calf raise', 'One leg floor calf raise', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'calves', 'ankles, feet', '', '', 'calves', '', '1. Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.
2. Lift one foot off the ground and balance on the other foot.
3. Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.
4. Pause for a moment at the top, then slowly lower your heel back down to the starting position.
5. Repeat for the desired number of repetitions, then switch legs and repeat.', '1387');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1476', 'One leg squat', 'One leg squat', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart.
2. Extend one leg forward, keeping it off the ground.
3. Bend your standing leg and lower your body down as if sitting back into a chair.
4. Keep your chest up and your back straight.
5. Push through your heel to return to the starting position.
6. Repeat with the other leg.', '1476');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0641', 'Otis up', 'Otis up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors, lower back', '', '', 'abs', 'hip-flexors,lower-back', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0641');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0642', 'Outside leg kick push-up', 'Outside leg kick push-up', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.
2. Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.
3. As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.
4. Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.
5. Continue alternating leg kicks and push-ups for the desired number of repetitions.', '0642');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0643', 'Overhead triceps stretch', 'Overhead triceps stretch', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Stand or sit upright with your feet shoulder-width apart.
2. Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.
3. With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.
4. Hold the stretch for 15-30 seconds, then release.
5. Repeat on the other side.', '0643');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3147', 'Pelvic tilt', 'Pelvic tilt', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'lower back', '', '', 'abs', 'lower-back', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands by your sides.
3. Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.
4. Hold this position for a few seconds, focusing on contracting your abs.
5. Release the tilt and return to the starting position.
6. Repeat for the desired number of repetitions.', '3147');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1422', 'Pelvic tilt into bridge', 'Pelvic tilt into bridge', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings, core', '', '', 'gluteal', 'hamstring,abs', '1. Lie on your back with your knees bent and feet flat on the ground.
2. Place your arms by your sides with your palms facing down.
3. Engage your glutes and core muscles.
4. Tilt your pelvis upward, lifting your hips off the ground.
5. Hold the bridge position for a few seconds.
6. Slowly lower your hips back down to the starting position.
7. Repeat for the desired number of repetitions.', '1422');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1388', 'Peroneals stretch', 'Peroneals stretch', 'legs', 'پا', 'other', 'سایر', 'calves', 'ankles, feet', '', '', 'calves', '', '1. Sit on the ground with your legs extended in front of you.
2. Loop the rope around the ball of your foot and hold the ends of the rope with your hands.
3. Gently pull the rope towards you, flexing your foot and stretching your calf muscles.
4. Hold the stretch for 15-30 seconds.
5. Release the tension on the rope and repeat the stretch on the other leg.
6. Repeat for the desired number of repetitions.', '1388');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3662', 'Pike-to-cobra push-up', 'Pike-to-cobra push-up', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'core, shoulders, triceps', '', '', 'gluteal', 'abs,deltoids,triceps', '1. Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.
2. Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.
3. Lower your upper body towards the ground by bending your elbows, keeping them close to your body.
4. As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.
5. Reverse the movement by bending your elbows and lowering your chest back down towards the ground.
6. Push through your hands to return to the inverted V position.
7. Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.
8. Repeat for the desired number of repetitions.', '3662');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1306', 'Plyo push up', 'Plyo push up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Start in a high plank position with your hands slightly wider than shoulder-width apart.
2. Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.
3. Push explosively off the ground, using your chest muscles to propel your upper body off the ground.
4. Land softly with your hands back in the starting position.
5. Repeat for the desired number of repetitions.', '1306');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1687', 'Posterior step to overhead reach', 'Posterior step to overhead reach', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'glutes, hamstrings, quadriceps, shoulders', '', '', 'abs', 'gluteal,hamstring,quadriceps,deltoids', '1. Stand with your feet hip-width apart and your arms by your sides.
2. Take a step back with your right foot, landing on the ball of your foot.
3. Bend your left knee and lower your body into a lunge position.
4. As you lower into the lunge, simultaneously reach your arms overhead.
5. Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.
6. Repeat the movement on the other side, stepping back with your left foot and bending your right knee.
7. Continue alternating sides for the desired number of repetitions.', '1687');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1389', 'Posterior tibialis stretch', 'Posterior tibialis stretch', 'legs', 'پا', 'other', 'سایر', 'calves', 'hamstrings, quadriceps', '', '', 'calves', 'hamstring,quadriceps', '1. Sit on the ground with your legs extended in front of you.
2. Loop the rope around the ball of your foot and hold the ends of the rope with your hands.
3. Gently pull the rope towards you, flexing your foot and stretching your calf muscles.
4. Hold the stretch for 20-30 seconds.
5. Release the tension on the rope and relax your foot.
6. Repeat the stretch on the other leg.', '1389');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3119', 'Potty squat', 'Potty squat', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'quadriceps, glutes', '', '', 'abs', 'quadriceps,gluteal', '1. Stand with your feet shoulder-width apart, toes pointing slightly outward.
2. Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.
3. Keep your chest up and your back straight throughout the movement.
4. Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.
5. Pause for a moment at the bottom, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '3119');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3132', 'Potty squat with support', 'Potty squat with support', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, toes pointing slightly outward.
2. Hold onto a stable support, such as a chair or wall, for balance.
3. Lower your body down into a squat position by bending your knees and pushing your hips back.
4. Keep your chest up and your back straight throughout the movement.
5. Pause for a moment at the bottom, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '3132');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0648', 'Power clean', 'Power clean', 'legs', 'پا', 'barbell', 'هالتر', 'hamstrings', 'glutes, quadriceps, calves', '', '', 'hamstring', 'gluteal,quadriceps,calves', '1. Start with the barbell on the ground in front of you, with your feet shoulder-width apart.
2. Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.
3. Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.
4. As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.
5. As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.
6. Stand up with the barbell, fully extending your hips and knees.
7. Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.
8. Repeat for the desired number of repetitions.', '0648');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3665', 'Power point plank', 'Power point plank', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'shoulders, triceps, glutes', '', '', 'abs', 'deltoids,triceps,gluteal', '1. Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.
2. Engage your core and squeeze your glutes to maintain a stable position.
3. Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.
4. Hold this position for the desired amount of time, keeping your core and glutes engaged.
5. To return to the starting position, push through your forearms and lift your body back up into a high plank position.
6. Repeat for the desired number of repetitions.', '3665');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3203', 'Prisoner half sit-up (male)', 'Prisoner half sit-up (male)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '3203');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1707', 'Prone twist on stability ball', 'Prone twist on stability ball', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'abs', 'obliques, lower back', '', '', 'abs', 'obliques,lower-back', '1. Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.
2. Place your hands behind your head or cross them over your chest.
3. Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.
4. Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.
5. Pause for a moment, then return to the starting position.
6. Repeat the rotation to the other side.
7. Continue alternating sides for the desired number of repetitions.', '1707');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0651', 'Pull up (neutral grip)', 'Pull up (neutral grip)', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.
2. Engage your core and squeeze your shoulder blades together.
3. Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.
4. Continue pulling until your chin is above the bar.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position with control.
6. Repeat for the desired number of repetitions.', '0651');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0650', 'Pull-in (on stability ball)', 'Pull-in (on stability ball)', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Place your hands on the sides of the stability ball for support.
3. Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.
4. Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.
5. Repeat for the desired number of repetitions.', '0650');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1689', 'Push and pull bodyweight', 'Push and pull bodyweight', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, deltoids', '', '', 'chest', 'triceps,deltoids', '1. Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.
2. Lower your chest towards the ground by bending your elbows, keeping your body straight.
3. Push through your palms to extend your arms and return to the starting position.
4. From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.
5. Push through your palms to extend your arms and return to the starting position.
6. Repeat for the desired number of repetitions.', '1689');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1307', 'Push up on bosu ball', 'Push up on bosu ball', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Place the bosu ball on the ground with the flat side facing up.
2. Position yourself in a push-up position with your hands on the outer edges of the bosu ball.
3. Engage your core and lower your body down towards the bosu ball by bending your elbows.
4. Push yourself back up to the starting position by extending your arms.
5. Repeat for the desired number of repetitions.', '1307');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0653', 'Push-up (bosu ball)', 'Push-up (bosu ball)', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Place the bosu ball on the ground with the flat side facing up.
2. Position yourself in a push-up position with your hands on the outer edges of the bosu ball.
3. Engage your core and lower your body down towards the bosu ball by bending your elbows.
4. Push yourself back up to the starting position by extending your arms.
5. Repeat for the desired number of repetitions.', '0653');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0655', 'Push-up (on stability ball)', 'Push-up (on stability ball)', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.
2. Extend your legs straight out behind you, balancing on your toes.
3. Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.
4. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '0655');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0656', 'Push-up (on stability ball)', 'Push-up (on stability ball)', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.
2. Extend your legs straight out behind you, balancing on your toes.
3. Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.
4. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '0656');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0659', 'Push-up (wall)', 'Push-up (wall)', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, deltoids', '', '', 'chest', 'triceps,deltoids', '1. Stand facing a wall, about arm''s length away.
2. Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.
3. Step back a few feet, keeping your body straight and your feet hip-width apart.
4. Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.
5. Push back up to the starting position, straightening your arms.
6. Repeat for the desired number of repetitions.', '0659');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0658', 'Push-up (wall) v. 2', 'Push-up (wall) v. 2', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Stand facing a wall, about arm''s length away.
2. Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.
3. Step back with your feet, keeping them hip-width apart.
4. Engage your core and keep your body in a straight line from head to heels.
5. Bend your elbows and lower your chest towards the wall, keeping your body straight.
6. Pause for a moment, then push yourself back to the starting position.
7. Repeat for the desired number of repetitions.', '0658');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0660', 'Push-up close-grip off dumbbell', 'Push-up close-grip off dumbbell', 'arms', 'بازو', 'dumbbell', 'دمبل', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Start in a push-up position with your hands placed close together, directly under your shoulders.
2. Hold a dumbbell in each hand, resting them on the ground.
3. Lower your body towards the ground by bending your elbows, keeping them close to your sides.
4. Push through your palms to extend your arms and return to the starting position.
5. Repeat for the desired number of repetitions.', '0660');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0661', 'Push-up inside leg kick', 'Push-up inside leg kick', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves, core', '', '', 'gluteal', 'quadriceps,hamstring,calves,abs', '1. Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.
2. Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.
3. As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.
4. Lower your leg back down and repeat the push-up, then switch to the other leg.
5. Continue alternating leg kicks with each push-up repetition.', '0661');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0663', 'Push-up medicine ball', 'Push-up medicine ball', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Start in a high plank position with your hands on the medicine ball, shoulder-width apart.
2. Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.
3. Push through your palms to extend your arms and return to the starting position.
4. Repeat for the desired number of repetitions.', '0663');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1467', 'Push-up on lower arms', 'Push-up on lower arms', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Start in a plank position with your forearms on the ground and elbows directly below your shoulders.
2. Engage your core and keep your body in a straight line from head to toe.
3. Lower your chest towards the ground by bending your elbows, keeping them close to your body.
4. Pause for a moment at the bottom, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '1467');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3145', 'Push-up plus', 'Push-up plus', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.
2. Lower your body towards the ground by bending your elbows, keeping them close to your sides.
3. Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.
4. At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.
5. Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '3145');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0664', 'Push-up to side plank', 'Push-up to side plank', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'shoulders, chest, triceps', '', '', 'abs', 'deltoids,chest,triceps', '1. Start in a push-up position with your hands shoulder-width apart and your body in a straight line.
2. Lower your body towards the ground by bending your elbows, keeping your core engaged.
3. Push back up to the starting position.
4. Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.
5. Hold the side plank position for a few seconds, then return to the starting position.
6. Repeat the push-up and side plank on the opposite side.
7. Continue alternating sides for the desired number of repetitions.', '0664');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3533', 'Quads', 'Quads', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'quads', 'hamstrings, glutes', '', '', 'quadriceps', 'hamstring,gluteal', '1. Stand with your feet shoulder-width apart.
2. Lower your body by bending your knees and pushing your hips back as if sitting on a chair.
3. Keep your chest up and your back straight.
4. Lower yourself until your thighs are parallel to the ground.
5. Push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '3533');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3201', 'Quarter sit-up', 'Quarter sit-up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '3201');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3552', 'Quick feet v. 2', 'Quick feet v. 2', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'quads', 'calves, hamstrings', '', '', 'quadriceps', 'calves,hamstring', '1. Stand with your feet shoulder-width apart and your arms by your sides.
2. Begin by rapidly moving your feet up and down, as if you were running in place.
3. Keep your movements quick and light, focusing on staying on the balls of your feet.
4. Continue for the desired duration or number of repetitions.', '3552');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0666', 'Raise single arm push-up', 'Raise single arm push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.
2. Extend one arm straight out to the side, parallel to the ground.
3. Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.
4. Push back up to the starting position, using your chest muscles to lift your body.
5. Repeat with the other arm extended.', '0666');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0668', 'Rear decline bridge', 'Rear decline bridge', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings, lower back', '', '', 'gluteal', 'hamstring,lower-back', '1. Lie on your back with your feet flat on the ground and your knees bent.
2. Place your arms by your sides with your palms facing down.
3. Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.
4. Hold this position for a few seconds, then slowly lower your hips back down to the starting position.
5. Repeat for the desired number of repetitions.', '0668');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0669', 'Rear deltoid stretch', 'Rear deltoid stretch', 'shoulders', 'سرشانه', 'bodyweight', 'وزن بدن', 'delts', 'trapezius, rhomboids', '', '', 'deltoids', 'trapezius,upper-back', '1. Stand tall with your feet shoulder-width apart.
2. Extend your right arm across your chest, placing your left hand on your right elbow.
3. Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.
4. Hold the stretch for 15-30 seconds, then release.
5. Repeat on the other side.', '0669');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0670', 'Rear pull-up', 'Rear pull-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.
2. Hang from the bar with your arms fully extended and your body straight.
3. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.
4. Continue pulling until your chin is above the bar.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '0670');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1582', 'Reclining big toe pose with rope', 'Reclining big toe pose with rope', 'legs', 'پا', 'other', 'سایر', 'hamstrings', 'calves, glutes', '', '', 'hamstring', 'calves,gluteal', '1. Lie on your back with your legs extended and your arms by your sides.
2. Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.
3. Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.
4. Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.
5. Repeat with your left leg.
6. Continue alternating legs for the desired number of repetitions.', '1582');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3236', 'Resistance band hip thrusts on knees (female)', 'Resistance band hip thrusts on knees (female)', 'legs', 'پا', 'other', 'سایر', 'glutes', 'hamstrings, quadriceps', '', '', 'gluteal', 'hamstring,quadriceps', '1. Start by kneeling on the ground with your knees hip-width apart and your feet flexed.
2. Wrap the resistance band around your thighs, just above your knees.
3. Place your hands on your hips or extend them out in front of you for balance.
4. Engage your glutes and core muscles.
5. Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.
6. Hold the position for a moment, then slowly lower your knees back down to the starting position.
7. Repeat for the desired number of repetitions.', '3236');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3007', 'Resistance band leg extension', 'Resistance band leg extension', 'legs', 'پا', 'other', 'سایر', 'quads', 'hamstrings', '', '', 'quadriceps', 'hamstring', '1. Attach the resistance band to a sturdy anchor point and secure it around your ankle.
2. Stand facing the anchor point with your feet shoulder-width apart.
3. Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.
4. Pause for a moment at the top, then slowly return your leg to the starting position.
5. Repeat for the desired number of repetitions, then switch legs.', '3007');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3123', 'Resistance band seated biceps curl', 'Resistance band seated biceps curl', 'arms', 'بازو', 'other', 'سایر', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a chair or bench with your back straight and feet flat on the ground.
2. Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.
3. Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.
4. Pause for a moment at the top, squeezing your biceps.
5. Inhale and slowly lower the resistance band back to the starting position.
6. Repeat for the desired number of repetitions.', '3123');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3124', 'Resistance band seated chest press', 'Resistance band seated chest press', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Sit on a chair or bench with your back straight and feet flat on the ground.
2. Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.
3. Extend your arms forward, pushing the resistance band away from your chest.
4. Pause for a moment at the end of the movement, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '3124');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3006', 'Resistance band seated hip abduction', 'Resistance band seated hip abduction', 'legs', 'پا', 'other', 'سایر', 'abductors', 'glutes, hamstrings', '', '', 'gluteal', 'hamstring', '1. Sit on a chair or bench with your back straight and feet flat on the ground.
2. Wrap the resistance band around your thighs, just above your knees.
3. Place your hands on the sides of the chair or bench for support.
4. Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.
5. Pause for a moment at the end of the movement, then slowly bring your knees back together.
6. Repeat for the desired number of repetitions.', '3006');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3122', 'Resistance band seated shoulder press', 'Resistance band seated shoulder press', 'shoulders', 'سرشانه', 'other', 'سایر', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Sit on a chair or bench with your back straight and feet flat on the ground.
2. Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.
3. Press the band overhead, extending your arms fully.
4. Pause for a moment at the top, then slowly lower the band back down to shoulder level.
5. Repeat for the desired number of repetitions.', '3122');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3144', 'Resistance band seated straight back row', 'Resistance band seated straight back row', 'back', 'پشت و زیربغل', 'other', 'سایر', 'upper back', 'biceps, shoulders', '', '', 'upper-back', 'biceps,deltoids', '1. Sit on the floor with your legs extended and loop the resistance band around your feet.
2. Hold the ends of the resistance band with your hands, palms facing each other.
3. Keep your back straight and lean slightly back, engaging your core.
4. Pull the resistance band towards your chest, squeezing your shoulder blades together.
5. Pause for a moment at the top, then slowly release the tension and return to the starting position.
6. Repeat for the desired number of repetitions.', '3144');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0872', 'Reverse crunch', 'Reverse crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Lie flat on your back with your arms extended along your sides.
2. Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.
3. Contract your abs and curl your hips off the floor, bringing your knees towards your chest.
4. Pause for a moment at the top, then slowly lower your hips back down to the starting position.
5. Repeat for the desired number of repetitions.', '0872');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0672', 'Reverse dip', 'Reverse dip', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Position yourself between two parallel bars with your arms fully extended and your body straight.
2. Lower your body by bending your elbows until your upper arms are parallel to the ground.
3. Pause for a moment, then push yourself back up to the starting position by straightening your arms.
4. Repeat for the desired number of repetitions.', '0672');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0673', 'Reverse grip machine lat pulldown', 'Reverse grip machine lat pulldown', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.
2. Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.
3. Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.
4. Pull the handles down towards your chest, squeezing your shoulder blades together.
5. Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.
6. Repeat for the desired number of repetitions.', '0673');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0674', 'Reverse grip pull-up', 'Reverse grip pull-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with an underhand grip, hands shoulder-width apart.
2. Hang from the bar with your arms fully extended and your body straight.
3. Engage your back muscles and pull your body up towards the bar, leading with your chest.
4. Continue pulling until your chin is above the bar.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '0674');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0675', 'Reverse hyper extension (on stability ball)', 'Reverse hyper extension (on stability ball)', 'legs', 'پا', 'other', 'سایر', 'glutes', 'hamstrings, lower back', '', '', 'gluteal', 'hamstring,lower-back', '1. Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.
2. Place your hands on the ground in front of you for stability.
3. Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0675');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1423', 'Reverse hyper on flat bench', 'Reverse hyper on flat bench', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings, lower back', '', '', 'gluteal', 'hamstring,lower-back', '1. Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.
2. Hold onto the bench for stability.
3. Keeping your legs straight, raise them up towards the ceiling as high as you can.
4. Squeeze your glutes at the top of the movement.
5. Slowly lower your legs back down to the starting position.
6. Repeat for the desired number of repetitions.', '1423');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3663', 'Reverse plank with leg lift', 'Reverse plank with leg lift', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'glutes, hamstrings, shoulders', '', '', 'abs', 'gluteal,hamstring,deltoids', '1. Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.
2. Press through your hands and lift your hips off the ground, coming into a reverse plank position.
3. Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.
4. Hold for a moment, then lower your leg back down.
5. Repeat with the other leg.
6. Continue alternating legs for the desired number of repetitions.', '3663');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0677', 'Ring dips', 'Ring dips', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Start by hanging from the rings with your arms fully extended and your body straight.
2. Lower your body by bending your elbows until your shoulders are below your elbows.
3. Push yourself back up to the starting position by straightening your arms.
4. Repeat for the desired number of repetitions.', '0677');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2571', 'Rocking frog stretch', 'Rocking frog stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings, quadriceps', '', '', 'gluteal', 'hamstring,quadriceps', '1. Start by kneeling on the ground with your knees hip-width apart.
2. Place your hands on the ground in front of you for support.
3. Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.
4. Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.
5. Hold this position for a few seconds, feeling a stretch in your glutes.
6. Slowly return to the starting position by bending your knees and lowering your hips back down.
7. Repeat for the desired number of repetitions.', '2571');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0678', 'Rocky pull-up pulldown', 'Rocky pull-up pulldown', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Stand in front of a pull-up bar with your feet shoulder-width apart.
2. Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.
3. Hang from the bar with your arms fully extended and your body straight.
4. Engage your back muscles and pull your body up towards the bar, leading with your chest.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '0678');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2208', 'Roller back stretch', 'Roller back stretch', 'back', 'پشت و زیربغل', 'other', 'سایر', 'spine', 'hamstrings, glutes', '', '', 'lower-back', 'hamstring,gluteal', '1. Start by sitting on the ground with your legs extended in front of you.
2. Place the roller perpendicular to your body, just below your glutes.
3. Slowly roll your body backwards, allowing the roller to move up your back.
4. Continue rolling until the roller reaches your upper back.
5. Pause for a moment, then slowly roll back to the starting position.
6. Repeat for the desired number of repetitions.', '2208');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2204', 'Roller body saw', 'Roller body saw', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'abs', 'shoulders, triceps, core', '', '', 'abs', 'deltoids,triceps', '1. Start in a plank position with your forearms on the roller and your body in a straight line.
2. Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.
3. Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.
4. Repeat for the desired number of repetitions.', '2204');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2205', 'Roller hip lat stretch', 'Roller hip lat stretch', 'legs', 'پا', 'other', 'سایر', 'glutes', 'hamstrings, quadriceps', '', '', 'gluteal', 'hamstring,quadriceps', '1. Start by kneeling on the ground with the roller positioned under your hips.
2. Place your hands on the roller for support.
3. Slowly roll the roller forward, extending your hips and stretching your glutes.
4. Hold the stretch for a few seconds, then roll back to the starting position.
5. Repeat for the desired number of repetitions.', '2205');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2202', 'Roller hip stretch', 'Roller hip stretch', 'legs', 'پا', 'other', 'سایر', 'glutes', 'hamstrings, quadriceps', '', '', 'gluteal', 'hamstring,quadriceps', '1. Start by sitting on the ground with your legs extended in front of you.
2. Place the roller under your glutes, just above your knees.
3. Lean back and place your hands on the ground behind you for support.
4. Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.
5. Pause for a moment at the end of the movement, feeling a stretch in your glutes.
6. Slowly roll the roller back to the starting position, extending your legs.
7. Repeat for the desired number of repetitions.', '2202');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2206', 'Roller reverse crunch', 'Roller reverse crunch', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.
2. Place the roller between your feet and grip it with your toes.
3. Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.
5. Repeat for the desired number of repetitions.', '2206');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2203', 'Roller seated shoulder flexor depresor retractor', 'Roller seated shoulder flexor depresor retractor', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'deltoids, triceps', '', '', 'chest', 'deltoids,triceps', '1. Sit on a flat surface with your legs extended in front of you.
2. Hold the roller with both hands, palms facing down, and place it on your thighs.
3. Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.
4. Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.
5. Repeat for the desired number of repetitions.', '2203');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2209', 'Roller seated single leg shoulder flexor depresor retractor', 'Roller seated single leg shoulder flexor depresor retractor', 'chest', 'سینه', 'other', 'سایر', 'pectorals', 'deltoids, triceps', '', '', 'chest', 'deltoids,triceps', '1. Sit on a flat surface with your legs extended in front of you.
2. Hold the roller with both hands, palms facing down, and place it on your thighs.
3. Lean back slightly and engage your core muscles.
4. Raise the roller up to shoulder level, keeping your arms straight.
5. Slowly lower the roller back down to your thighs.
6. Repeat for the desired number of repetitions.', '2209');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2207', 'Roller side lat stretch', 'Roller side lat stretch', 'back', 'پشت و زیربغل', 'other', 'سایر', 'lats', 'shoulders, triceps', '', '', 'upper-back', 'deltoids,triceps', '1. Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.
4. Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.
5. Repeat for the desired number of repetitions.', '2207');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0680', 'Rope climb', 'Rope climb', 'back', 'پشت و زیربغل', 'other', 'سایر', 'upper back', 'forearms, biceps, shoulders', '', '', 'upper-back', 'forearm,biceps,deltoids', '1. Stand facing the rope with your feet shoulder-width apart.
2. Grab the rope with both hands, palms facing towards you.
3. Bend your knees slightly and engage your core.
4. Begin pulling yourself up the rope by alternating hand-over-hand movements.
5. Use your legs to assist in the upward movement.
6. Continue climbing until you reach the desired height or the top of the rope.
7. To descend, reverse the hand-over-hand movement while controlling your descent.
8. Repeat for the desired number of repetitions.', '0680');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1585', 'Runners stretch', 'Runners stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'hamstrings', 'calves, quadriceps', '', '', 'hamstring', 'calves,quadriceps', '1. Stand with your feet hip-width apart.
2. Take a step forward with your right foot, keeping your left foot planted.
3. Bend your right knee and lower your body down, keeping your left leg straight.
4. Place your hands on your right thigh for support.
5. Hold the stretch for 20-30 seconds, then switch sides and repeat.', '1585');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3012', 'Scapula dips', 'Scapula dips', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'traps', 'rhomboids, deltoids', '', '', 'trapezius', 'upper-back,deltoids', '1. Start by standing with your feet shoulder-width apart and your arms extended in front of you.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.
4. Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.
5. Repeat for the desired number of repetitions.', '3012');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3021', 'Scapula push-up', 'Scapula push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'serratus anterior', 'triceps, shoulders', '', '', 'serratus', 'triceps,deltoids', '1. Start in a high plank position with your hands directly under your shoulders and your body in a straight line.
2. Lower your chest towards the ground, keeping your elbows close to your body.
3. As you lower, squeeze your shoulder blades together and push your chest forward.
4. Pause for a moment at the bottom, then push back up to the starting position.
5. Repeat for the desired number of repetitions.', '3021');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0688', 'Scapular pull-up', 'Scapular pull-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'traps', 'biceps, rhomboids, rear deltoids', '', '', 'trapezius', 'biceps,upper-back,deltoids', '1. Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.
2. Retract your shoulder blades by pulling them down and back.
3. Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.
4. Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0688');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1390', 'Seated calf stretch (male)', 'Seated calf stretch (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'calves', 'hamstrings', '', '', 'calves', 'hamstring', '1. Sit on the edge of a chair or bench with your feet flat on the ground.
2. Extend one leg straight out in front of you, keeping your heel on the ground.
3. Lean forward slightly, feeling a stretch in your calf muscle.
4. Hold the stretch for 20-30 seconds.
5. Switch legs and repeat the stretch.', '1390');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1424', 'Seated glute stretch', 'Seated glute stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings', '', '', 'gluteal', 'hamstring', '1. Sit on the ground with your legs extended in front of you.
2. Bend your right knee and cross your right ankle over your left thigh.
3. Place your right hand on the ground behind you for support.
4. With your left hand, gently press down on your right knee to deepen the stretch.
5. Hold the stretch for 30 seconds to 1 minute.
6. Switch sides and repeat.', '1424');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0689', 'Seated leg raise', 'Seated leg raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Sit on a flat bench with your back straight and your feet flat on the ground.
2. Place your hands on the sides of the bench for support.
3. Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0689');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0690', 'Seated lower back stretch', 'Seated lower back stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'glutes, hamstrings', '', '', 'upper-back', 'gluteal,hamstring', '1. Sit on the edge of a chair with your feet flat on the ground.
2. Place your hands on your thighs or on the sides of the chair for support.
3. Slowly lean forward from your hips, keeping your back straight.
4. Feel the stretch in your lower back and hold for 20-30 seconds.
5. Slowly return to the starting position and repeat for the desired number of repetitions.', '0690');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2567', 'Seated piriformis stretch', 'Seated piriformis stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings', '', '', 'gluteal', 'hamstring', '1. Sit on the ground with your legs extended in front of you.
2. Bend your right knee and place your right foot on the outside of your left knee.
3. Place your left elbow on the outside of your right knee and gently twist your torso to the right.
4. Hold the stretch for 20-30 seconds, then switch sides and repeat.', '2567');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0691', 'Seated side crunch (wall)', 'Seated side crunch (wall)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques', '', '', 'abs', 'obliques', '1. Sit on the floor with your back against a wall and your legs extended in front of you.
2. Bend your knees and place your feet flat on the floor, hip-width apart.
3. Place your hands behind your head with your elbows pointing outwards.
4. Engage your abs and lean to one side, bringing your elbow towards your hip.
5. Pause for a moment, then return to the starting position.
6. Repeat on the other side.
7. Continue alternating sides for the desired number of repetitions.', '0691');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1587', 'Seated wide angle pose sequence', 'Seated wide angle pose sequence', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'hamstrings', 'quadriceps, calves', '', '', 'hamstring', 'quadriceps,calves', '1. Sit on the ground with your legs extended in a wide angle.
2. Flex your feet and engage your quadriceps.
3. Place your hands on the ground behind you for support.
4. Keeping your back straight, lean forward from your hips.
5. Continue leaning forward until you feel a stretch in your hamstrings.
6. Hold this position for a few breaths.
7. Slowly release the stretch and return to the starting position.
8. Repeat for the desired number of repetitions.', '1587');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0697', 'Self assisted inverse leg curl', 'Self assisted inverse leg curl', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'hamstrings', 'glutes, calves', '', '', 'hamstring', 'gluteal,calves', '1. Lie flat on your back on a mat or bench with your legs extended.
2. Place your hands by your sides or under your glutes for support.
3. Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.
4. Pause for a moment at the top, then slowly lower your legs back to the starting position.
5. Repeat for the desired number of repetitions.', '0697');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1766', 'Self assisted inverse leg curl', 'Self assisted inverse leg curl', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'hamstrings', 'glutes, calves', '', '', 'hamstring', 'gluteal,calves', '1. Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.
2. Place your hands on the side handles of the machine for support.
3. Keeping your upper body stationary, exhale and curl your legs upward as far as possible.
4. Hold the contracted position for a brief pause as you squeeze your hamstrings.
5. Slowly lower your legs back to the starting position while inhaling.
6. Repeat for the desired number of repetitions.', '1766');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0696', 'Self assisted inverse leg curl (on floor)', 'Self assisted inverse leg curl (on floor)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'hamstrings', 'glutes, calves', '', '', 'hamstring', 'gluteal,calves', '1. Lie flat on your back with your legs extended and your arms by your sides.
2. Bend your knees and place your feet flat on the ground, hip-width apart.
3. Lift your hips off the ground, engaging your glutes and hamstrings.
4. Slowly curl your legs towards your glutes, keeping your hips lifted.
5. Pause for a moment at the top, then slowly extend your legs back to the starting position.
6. Lower your hips back down to the ground.
7. Repeat for the desired number of repetitions.', '0696');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1763', 'Shoulder grip pull-up', 'Shoulder grip pull-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with a shoulder-width grip, palms facing away from you.
2. Hang freely with your arms fully extended.
3. Engage your back muscles and pull your body up towards the bar until your chin is above the bar.
4. Pause for a moment at the top, then slowly lower your body back down to the starting position.
5. Repeat for the desired number of repetitions.', '1763');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3699', 'Shoulder tap', 'Shoulder tap', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'shoulders, triceps', '', '', 'abs', 'deltoids,triceps', '1. Start in a high plank position with your hands directly under your shoulders and your body in a straight line.
2. Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.
3. Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.
4. Continue alternating shoulder taps while keeping your hips and torso stable.
5. Repeat for the desired number of repetitions.', '3699');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0699', 'Shoulder tap push-up', 'Shoulder tap push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, core', '', '', 'chest', 'triceps,abs', '1. Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.
2. Lower your body towards the ground by bending your elbows, keeping them close to your sides.
3. As you push back up, lift your right hand off the ground and tap your left shoulder.
4. Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.
5. Continue alternating shoulder taps with each push-up repetition.
6. Maintain a stable core and avoid excessive hip rotation throughout the exercise.
7. Repeat for the desired number of repetitions.', '0699');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1774', 'Side bridge hip abduction', 'Side bridge hip abduction', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'abductors', 'glutes, obliques', '', '', 'gluteal', 'obliques', '1. Lie on your side with your legs extended and stacked on top of each other.
2. Prop yourself up on your forearm, keeping your elbow directly below your shoulder.
3. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.
4. While keeping your core engaged, lift your top leg as high as possible without rotating your hips.
5. Pause for a moment at the top, then lower your leg back down.
6. Repeat for the desired number of repetitions, then switch sides.', '1774');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0705', 'Side bridge v. 2', 'Side bridge v. 2', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, glutes', '', '', 'abs', 'obliques,gluteal', '1. Lie on your side with your legs extended and stacked on top of each other.
2. Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.
3. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.
4. Hold this position for the desired amount of time.
5. Lower your hips back down to the starting position.
6. Repeat on the other side.', '0705');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0709', 'Side hip (on parallel bars)', 'Side hip (on parallel bars)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, hip flexors', '', '', 'abs', 'obliques,hip-flexors', '1. Stand between two parallel bars with your feet shoulder-width apart.
2. Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.
3. Engage your abs and slowly lift your legs to the side, keeping them straight.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0709');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0710', 'Side hip abduction', 'Side hip abduction', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'abductors', 'glutes, quadriceps', '', '', 'gluteal', 'quadriceps', '1. Stand with your feet shoulder-width apart and your hands on your hips.
2. Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.
3. Pause for a moment at the top, then slowly lower your leg back down to the starting position.
4. Repeat on the other side.
5. Continue alternating sides for the desired number of repetitions.', '0710');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1358', 'Side lying floor stretch', 'Side lying floor stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'obliques, glutes', '', '', 'upper-back', 'obliques,gluteal', '1. Lie on your side with your legs straight and your bottom arm extended straight overhead.
2. Bend your top knee and place your foot on the ground in front of your bottom leg.
3. Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.
4. Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.
5. Hold the stretch for 20-30 seconds, then slowly lower your leg back down.
6. Repeat on the other side.', '1358');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3667', 'Side lying hip adduction (male)', 'Side lying hip adduction (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'adductors', 'glutes, hamstrings', '', '', 'adductors', 'gluteal,hamstring', '1. Lie on your side with your legs straight and stacked on top of each other.
2. Place your bottom arm under your head for support.
3. Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.
4. Pause for a moment at the top, then slowly lower your leg back down to the starting position.
5. Repeat for the desired number of repetitions, then switch sides.', '3667');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1775', 'Side plank hip adduction', 'Side plank hip adduction', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'adductors', 'obliques, glutes', '', '', 'adductors', 'obliques,gluteal', '1. Start by lying on your side with your legs extended and stacked on top of each other.
2. Prop yourself up on your forearm, keeping your elbow directly below your shoulder.
3. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.
4. While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.
5. Slowly lower your leg back down to the starting position.
6. Repeat for the desired number of repetitions, then switch sides.', '1775');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0717', 'Side push-up', 'Side push-up', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'shoulders, chest, core', '', '', 'triceps', 'deltoids,chest,abs', '1. Start by lying on your side with your legs extended and stacked on top of each other.
2. Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.
3. Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.
4. Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.
5. Lower your body back down to the starting position with control.
6. Repeat for the desired number of repetitions, then switch sides.', '0717');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0721', 'Side wrist pull stretch', 'Side wrist pull stretch', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'forearms', 'wrists, hands', '', '', 'forearm', '', '1. Stand with your feet shoulder-width apart and your arms extended in front of you.
2. Extend your right arm out to the side, parallel to the ground, with your palm facing down.
3. With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.
4. Hold the stretch for 15-30 seconds, then release.
5. Repeat on the other side.', '0721');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0720', 'Side-to-side chin', 'Side-to-side chin', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.
3. Hang from the bar with your arms fully extended and your body relaxed.
4. Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.
5. Once your chin is above the bar, lower yourself back down to the starting position.
6. Repeat for the desired number of repetitions.', '0720');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3213', 'Side-to-side toe touch (male)', 'Side-to-side toe touch (male)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, hip flexors', '', '', 'abs', 'obliques,hip-flexors', '1. Stand with your feet shoulder-width apart and your arms extended to the sides.
2. Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.
3. Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.
4. Repeat the side-to-side bending motion for the desired number of repetitions.', '3213');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0725', 'Single arm push-up', 'Single arm push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.
2. Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.
3. As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.
4. Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.
5. Repeat the movement, alternating the arm you extend with each repetition.', '0725');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3645', 'Single leg bridge with outstretched leg', 'Single leg bridge with outstretched leg', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings, quadriceps', '', '', 'gluteal', 'hamstring,quadriceps', '1. Lie on your back with your knees bent and feet flat on the ground.
2. Extend one leg straight out in front of you.
3. Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.
4. Hold for a moment at the top, then slowly lower your hips back down to the starting position.
5. Repeat for the desired number of repetitions, then switch legs.', '3645');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0727', 'Single leg calf raise (on a dumbbell)', 'Single leg calf raise (on a dumbbell)', 'legs', 'پا', 'dumbbell', 'دمبل', 'calves', 'ankles, feet', '', '', 'calves', '', '1. Stand with your feet hip-width apart and hold a dumbbell in one hand.
2. Lift one foot off the ground and balance on the other foot.
3. Slowly raise your heel as high as possible, using your calf muscles.
4. Pause for a moment at the top, then slowly lower your heel back down.
5. Repeat for the desired number of repetitions, then switch to the other leg.', '0727');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0730', 'Single leg platform slide', 'Single leg platform slide', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'hamstrings', 'glutes, quadriceps', '', '', 'hamstring', 'gluteal,quadriceps', '1. Start by standing with one foot on a platform or slide board.
2. Bend your knee slightly and slide the foot on the platform backward, extending your leg.
3. Keep your core engaged and maintain a straight posture throughout the movement.
4. Slowly return to the starting position by sliding your foot back to the initial position.
5. Repeat the movement for the desired number of repetitions, then switch legs.', '0730');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1759', 'Single leg squat (pistol) male', 'Single leg squat (pistol) male', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart and arms extended in front of you.
2. Lift your right foot off the ground and extend it forward.
3. Slowly lower your body down by bending your left knee and pushing your hips back.
4. Keep your chest up and your back straight as you lower yourself down.
5. Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.
6. Pause for a moment at the bottom, then push through your left heel to return to the starting position.
7. Repeat for the desired number of repetitions, then switch legs.', '1759');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1489', 'Sissy squat', 'Sissy squat', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'quads', 'calves, glutes', '', '', 'quadriceps', 'calves,gluteal', '1. Stand with your feet shoulder-width apart and your toes pointing slightly outward.
2. Hold onto a stable object for balance if needed.
3. Slowly lower your body by bending your knees and leaning back, keeping your torso upright.
4. Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.
5. Pause for a moment, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '1489');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0735', 'Sit-up v. 2', 'Sit-up v. 2', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0735');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3679', 'Sit-up with arms on chest', 'Sit-up with arms on chest', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Cross your arms over your chest.
3. Engaging your abs, lift your upper body off the ground towards your knees.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '3679');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2142', 'Ski ergometer', 'Ski ergometer', 'arms', 'بازو', 'other', 'سایر', 'triceps', 'shoulders, forearms', '', '', 'triceps', 'deltoids,forearm', '1. Adjust the seat height and footrests to a comfortable position.
2. Grasp the handles with an overhand grip, palms facing down.
3. Sit up straight with your feet flat on the footrests.
4. Extend your arms straight out in front of you, keeping your elbows slightly bent.
5. Engage your triceps and push the handles down towards your thighs.
6. Pause for a moment at the bottom, then slowly return to the starting position.
7. Repeat for the desired number of repetitions.', '2142');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3304', 'Skin the cat', 'Skin the cat', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'upper back', 'shoulders, core', '', '', 'upper-back', 'deltoids,abs', '1. Start by hanging from a bar with your arms fully extended and your body relaxed.
2. Engage your core and lift your legs up, bringing your knees towards your chest.
3. Continue to lift your legs up and over your head, allowing your body to pass through the arms.
4. Once your legs are fully extended over your head, begin to lower them back down towards the starting position.
5. As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.
6. Repeat for the desired number of repetitions.', '3304');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1425', 'Sled 45 degrees one leg press', 'Sled 45 degrees one leg press', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the sled machine to a 45-degree angle.
2. Sit on the sled machine with your back against the pad and your feet on the footplate.
3. Place one foot on the footplate and extend your leg, pushing the sled away from you.
4. Slowly bend your knee and lower the sled back to the starting position.
5. Repeat with the other leg.
6. Continue alternating legs for the desired number of repetitions.', '1425');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0738', 'Sled 45в° calf press', 'Sled 45в° calf press', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'hamstrings', '', '', 'calves', 'hamstring', '1. Adjust the sled machine to a 45-degree angle.
2. Place your feet on the sled platform with your toes pointing forward.
3. Push the sled platform away from you by extending your ankles and calves.
4. Pause for a moment at the top, then slowly lower the sled platform back to the starting position.
5. Repeat for the desired number of repetitions.', '0738');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0739', 'Sled 45в° leg press', 'Sled 45в° leg press', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the seat and footplate of the sled machine to a comfortable position.
2. Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.
3. Grip the handles on the sides of the seat for stability.
4. Push the footplate away from your body by extending your legs, keeping your heels on the footplate.
5. Continue pushing until your legs are almost fully extended, but without locking your knees.
6. Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.
7. Repeat for the desired number of repetitions.', '0739');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1464', 'Sled 45в° leg press (back pov)', 'Sled 45в° leg press (back pov)', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the seat of the sled machine so that your knees are at a 45-degree angle.
2. Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.
3. Grip the handles on the sides of the seat for stability.
4. Push the footplate away from your body by extending your legs, keeping your heels on the footplate.
5. Pause for a moment at the fully extended position.
6. Slowly bend your knees and lower the footplate back towards your body, controlling the movement.
7. Repeat for the desired number of repetitions.', '1464');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1463', 'Sled 45° leg press (side pov)', 'Sled 45° leg press (side pov)', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.
2. Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.
3. Grip the handles on the sides of the seat for stability.
4. Push against the footplate to extend your legs, straightening them completely.
5. Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.
6. Repeat for the desired number of repetitions.', '1463');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0740', 'Sled 45в° leg wide press', 'Sled 45в° leg wide press', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the sled machine to a 45-degree angle.
2. Sit on the sled machine with your back against the pad and your feet on the foot platform.
3. Position your feet wider than shoulder-width apart.
4. Push against the foot platform to extend your legs and straighten your knees.
5. Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.
6. Repeat for the desired number of repetitions.', '0740');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1391', 'Sled calf press on leg press', 'Sled calf press on leg press', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'hamstrings, quadriceps', '', '', 'calves', 'hamstring,quadriceps', '1. Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.
2. Place your feet shoulder-width apart on the sled, with your toes pointing forward.
3. Release the safety handles and push the sled away from you by extending your knees and ankles.
4. Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.
5. Repeat for the desired number of repetitions.', '1391');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0741', 'Sled closer hack squat', 'Sled closer hack squat', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.
2. Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.
3. Grip the handles on the sides of the machine for stability.
4. Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.
5. Continue lowering until your thighs are parallel to the ground or slightly below.
6. Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.
7. Repeat for the desired number of repetitions.', '0741');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0742', 'Sled forward angled calf raise', 'Sled forward angled calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.
2. Place your hands on the handles or the sides of the machine for support.
3. Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.
4. Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.
5. Repeat for the desired number of repetitions.', '0742');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0743', 'Sled hack squat', 'Sled hack squat', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the sled machine to a comfortable position for your height.
2. Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.
3. Hold onto the handles or bars for stability.
4. Lower your body by bending your knees and hips, keeping your back straight and chest up.
5. Continue lowering until your thighs are parallel to the ground or slightly below.
6. Pause for a moment, then push through your heels to raise your body back up to the starting position.
7. Repeat for the desired number of repetitions.', '0743');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2334', 'Sled lying calf press', 'Sled lying calf press', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Adjust the sled machine to a comfortable weight.
2. Sit on the sled machine with your back against the pad and your feet on the platform.
3. Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.
4. Push the platform away from you by extending your ankles, keeping your knees slightly bent.
5. Continue pushing until your calves are fully contracted.
6. Hold the contraction for a moment, then slowly lower the platform back to the starting position.
7. Repeat for the desired number of repetitions.', '2334');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0744', 'Sled lying squat', 'Sled lying squat', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the sled machine to a comfortable weight.
2. Lie on your back on the sled machine with your feet on the footplate.
3. Position your feet shoulder-width apart and slightly angled outwards.
4. Grip the handles of the sled machine for stability.
5. Engage your glutes and core muscles.
6. Push through your heels and extend your legs to lift the sled.
7. Lower the sled back down by bending your knees and hips.
8. Repeat for the desired number of repetitions.', '0744');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1392', 'Sled one leg calf press on leg press', 'Sled one leg calf press on leg press', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.
2. Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.
3. Place your toes and the balls of your feet on the sled, keeping your heels off.
4. Push the sled forward by extending your ankles, keeping your knees slightly bent.
5. Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.
6. Repeat for the desired number of repetitions.', '1392');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1496', 'Sledge hammer', 'Sledge hammer', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'abs', 'forearms, shoulders', '', '', 'abs', 'forearm,deltoids', '1. Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.
2. Engage your core and keep your back straight.
3. Swing the sledge hammer down towards the ground, using your core and upper body strength.
4. As you swing down, pivot your hips and transfer the force to the hammer.
5. Repeat for the desired number of repetitions.', '1496');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0746', 'Smith back shrug', 'Smith back shrug', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'traps', 'shoulders', '', '', 'trapezius', 'deltoids', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
3. Keep your arms straight and allow the barbell to hang in front of your thighs.
4. Lift your shoulders straight up towards your ears, squeezing your traps at the top.
5. Hold for a moment, then lower your shoulders back down to the starting position.
6. Repeat for the desired number of repetitions.', '0746');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0747', 'Smith behind neck press', 'Smith behind neck press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Adjust the seat height of the smith machine so that the bar is at shoulder level.
2. Stand with your feet shoulder-width apart and your knees slightly bent.
3. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
4. Lift the bar off the rack and step back, maintaining a stable stance.
5. Lower the bar down to the back of your neck, keeping your elbows pointing forward.
6. Press the bar up overhead until your arms are fully extended.
7. Pause for a moment at the top, then slowly lower the bar back down to the starting position.
8. Repeat for the desired number of repetitions.', '0747');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0748', 'Smith bench press', 'Smith bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Adjust the height of the smith machine bar to chest level.
2. Lie flat on the bench with your feet firmly planted on the ground.
3. Grip the bar with an overhand grip slightly wider than shoulder-width apart.
4. Unrack the bar and lower it towards your chest, keeping your elbows tucked in.
5. Pause for a moment when the bar touches your chest.
6. Push the bar back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '0748');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0749', 'Smith bent knee good morning', 'Smith bent knee good morning', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'hamstrings, lower back', '', '', 'gluteal', 'hamstring,lower-back', '1. Start by standing with your feet shoulder-width apart, toes pointing forward.
2. Place the barbell across your upper back, resting it on your traps.
3. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
4. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.
5. Engage your glutes and hamstrings to raise your torso back up to the starting position.
6. Repeat for the desired number of repetitions.', '0749');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1359', 'Smith bent over row', 'Smith bent over row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'upper back', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Set up the smith machine with the bar at hip height.
2. Stand facing the bar with your feet shoulder-width apart.
3. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
4. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.
5. Pull the bar towards your lower chest, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly lower the bar back down to the starting position.
7. Repeat for the desired number of repetitions.', '1359');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0750', 'Smith chair squat', 'Smith chair squat', 'legs', 'پا', 'machine', 'دستگاه', 'quads', 'glutes, hamstrings, calves', '', '', 'quadriceps', 'gluteal,hamstring,calves', '1. Adjust the height of the smith machine bar to a comfortable position.
2. Stand with your feet shoulder-width apart, toes slightly turned out.
3. Place the barbell across your upper back, resting it on your traps.
4. Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.
5. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
6. Pause for a moment, then push through your heels to return to the starting position.
7. Repeat for the desired number of repetitions.', '0750');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0751', 'Smith close-grip bench press', 'Smith close-grip bench press', 'arms', 'بازو', 'machine', 'دستگاه', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Adjust the seat height and position yourself on the bench with your feet flat on the ground.
2. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.
3. Lower the barbell towards your chest, keeping your elbows close to your body.
4. Pause for a moment at the bottom, then push the barbell back up to the starting position.
5. Repeat for the desired number of repetitions.', '0751');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0752', 'Smith deadlift', 'Smith deadlift', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'hamstrings, quadriceps, lower back', '', '', 'gluteal', 'hamstring,quadriceps,lower-back', '1. Set up the smith machine with the bar at hip height.
2. Stand with your feet shoulder-width apart, toes pointing slightly outward.
3. Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.
4. Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.
5. Stand up straight, fully extending your hips and knees.
6. Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.
7. Repeat for the desired number of repetitions.', '0752');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0753', 'Smith decline bench press', 'Smith decline bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Adjust the decline bench to the desired angle.
2. Lie down on the bench with your feet secured under the foot pads.
3. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.
5. Pause for a moment at the bottom, then push the barbell back up to the starting position.
6. Repeat for the desired number of repetitions.', '0753');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0754', 'Smith decline reverse-grip press', 'Smith decline reverse-grip press', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Adjust the smith machine to a decline position.
2. Lie down on the bench with your feet secured under the foot pads.
3. Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.
4. Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.
5. Pause for a moment at the bottom, then push the barbell back up to the starting position.
6. Repeat for the desired number of repetitions.', '0754');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1433', 'Smith front squat (clean grip)', 'Smith front squat (clean grip)', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves, core', '', '', 'gluteal', 'quadriceps,hamstring,calves,abs', '1. Set up the smith machine with the barbell at shoulder height.
2. Stand facing the barbell with your feet shoulder-width apart.
3. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
4. Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.
5. Keep your chest up, back straight, and core engaged.
6. Lower your body by bending at the knees and hips, as if sitting back into a chair.
7. Continue lowering until your thighs are parallel to the ground or slightly below.
8. Pause for a moment, then push through your heels to return to the starting position.
9. Repeat for the desired number of repetitions.', '1433');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3281', 'Smith full squat', 'Smith full squat', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Set up the smith machine with the barbell at shoulder height.
2. Stand with your feet shoulder-width apart, toes slightly turned out.
3. Step under the bar and position it across your upper back, resting on your traps.
4. Grip the bar with your hands slightly wider than shoulder-width apart.
5. Unrack the bar and take a step back, maintaining a stable stance.
6. Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.
7. Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.
8. Pause for a moment at the bottom, then drive through your heels to return to the starting position.
9. Repeat for the desired number of repetitions.', '3281');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0755', 'Smith hack squat', 'Smith hack squat', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the barbell on the smith machine to an appropriate height for your body.
2. Stand with your feet shoulder-width apart, toes slightly pointed outwards.
3. Position yourself under the barbell, resting it on your upper traps and shoulders.
4. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
5. Engage your core and keep your chest up as you unrack the barbell.
6. Take a step back and position your feet slightly wider than shoulder-width apart.
7. Bend your knees and lower your body down, keeping your chest up and back straight.
8. Continue descending until your thighs are parallel to the ground or slightly below.
9. Pause for a moment at the bottom, then push through your heels to return to the starting position.
10. Repeat for the desired number of repetitions.', '0755');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0756', 'Smith hip raise', 'Smith hip raise', 'core', 'شکم و میان‌تنه', 'machine', 'دستگاه', 'abs', 'glutes, hamstrings', '', '', 'abs', 'gluteal,hamstring', '1. Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.
2. Place your hands on the barbell, slightly wider than shoulder-width apart.
3. Engage your core and glutes, then push through your heels to raise your hips off the ground.
4. Continue lifting until your body forms a straight line from your knees to your shoulders.
5. Hold for a moment at the top, then slowly lower your hips back down to the starting position.
6. Repeat for the desired number of repetitions.', '0756');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0757', 'Smith incline bench press', 'Smith incline bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Adjust the bench to a 30-45 degree incline.
2. Sit on the bench with your back flat against the pad and feet firmly on the ground.
3. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.
5. Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '0757');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0758', 'Smith incline reverse-grip press', 'Smith incline reverse-grip press', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Adjust the seat of the smith machine to a comfortable incline angle.
2. Sit on the machine with your back against the pad and your feet flat on the ground.
3. Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.
4. Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.
5. Pause for a moment when the bar is just above your chest.
6. Push the bar back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '0758');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0759', 'Smith incline shoulder raises', 'Smith incline shoulder raises', 'chest', 'سینه', 'machine', 'دستگاه', 'serratus anterior', 'deltoids, trapezius', '', '', 'serratus', 'deltoids,trapezius', '1. Adjust the smith machine to an incline position.
2. Stand facing the machine with your feet shoulder-width apart.
3. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
4. Keep your back straight and core engaged.
5. Raise the barbell up towards the ceiling, leading with your elbows.
6. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
7. Repeat for the desired number of repetitions.', '0759');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0760', 'Smith leg press', 'Smith leg press', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the seat and footplate of the smith machine to a comfortable position.
2. Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.
3. Grasp the handles or sides of the machine for stability.
4. Push the footplate away from you by extending your legs, keeping your back against the backrest.
5. Pause for a moment at the fully extended position.
6. Slowly bend your knees and lower the footplate back towards you, returning to the starting position.
7. Repeat for the desired number of repetitions.', '0760');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1434', 'Smith low bar squat', 'Smith low bar squat', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.
2. Stand with your feet shoulder-width apart, toes slightly turned outwards.
3. Step under the bar and position it across your upper back, resting it on your traps.
4. Grip the bar with your hands slightly wider than shoulder-width apart.
5. Unrack the bar by straightening your legs and stepping back from the rack.
6. Take a deep breath and brace your core.
7. Initiate the squat by pushing your hips back and bending your knees.
8. Lower your body until your thighs are parallel to the ground or slightly below.
9. Keep your chest up and your back straight throughout the movement.
10. Drive through your heels to stand back up, extending your hips and knees.
11. Repeat for the desired number of repetitions.', '1434');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1683', 'Smith machine bicep curl', 'Smith machine bicep curl', 'arms', 'بازو', 'machine', 'دستگاه', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Adjust the height of the smith machine bar to be at waist level.
2. Stand facing the smith machine with your feet shoulder-width apart.
3. Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.
4. Keep your elbows close to your sides and your upper arms stationary.
5. Exhale and curl the bar up towards your shoulders, contracting your biceps.
6. Pause for a moment at the top of the movement, squeezing your biceps.
7. Inhale and slowly lower the bar back down to the starting position.
8. Repeat for the desired number of repetitions.', '1683');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1625', 'Smith machine decline close grip bench press', 'Smith machine decline close grip bench press', 'arms', 'بازو', 'machine', 'دستگاه', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Adjust the bench on the smith machine to a decline position.
2. Lie down on the bench with your feet firmly planted on the ground.
3. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.
5. Pause for a moment when the barbell is just above your chest.
6. Push the barbell back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '1625');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1752', 'Smith machine incline tricep extension', 'Smith machine incline tricep extension', 'arms', 'بازو', 'machine', 'دستگاه', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Adjust the seat of the smith machine so that the bar is at shoulder height.
2. Sit on the bench with your back against the pad and your feet flat on the ground.
3. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
4. Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.
5. Lower the bar slowly towards your forehead, keeping your elbows close to your head.
6. Pause for a moment at the bottom, then push the bar back up to the starting position.
7. Repeat for the desired number of repetitions.', '1752');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1626', 'Smith machine reverse decline close grip bench press', 'Smith machine reverse decline close grip bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Adjust the smith machine to a decline position.
2. Lie down on the bench with your feet secured under the foot pads.
3. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.
5. Pause for a moment at the bottom, then push the barbell back up to the starting position.
6. Repeat for the desired number of repetitions.', '1626');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0761', 'Smith narrow row', 'Smith narrow row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'upper back', 'biceps, rear deltoids', '', '', 'upper-back', 'biceps,deltoids', '1. Adjust the seat height and position yourself on the machine with your feet flat on the floor.
2. Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.
3. Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.
4. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.
5. Repeat for the desired number of repetitions.', '0761');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1360', 'Smith one arm row', 'Smith one arm row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'upper back', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Adjust the height of the smith machine bar to waist level.
2. Stand facing the smith machine with your feet shoulder-width apart.
3. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
4. Grasp the bar with one hand using an overhand grip, with your palm facing down.
5. Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.
6. Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.
7. Repeat for the desired number of repetitions, then switch to the other arm.', '1360');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1393', 'Smith one leg floor calf raise', 'Smith one leg floor calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Position yourself on the floor under the smith machine bar, facing away from the machine.
2. Place the balls of your feet on a raised surface, such as a weight plate or block.
3. Position the smith machine bar across your lower legs, just above your ankles.
4. Hold onto the bar with your hands for stability.
5. Raise your heels off the ground by extending your ankles, lifting your body up.
6. Pause at the top of the movement, then slowly lower your heels back down to the starting position.
7. Repeat for the desired number of repetitions.', '1393');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0762', 'Smith rear delt row', 'Smith rear delt row', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'trapezius, rhomboids, biceps', '', '', 'deltoids', 'trapezius,upper-back,biceps', '1. Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.
2. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
3. Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.
4. Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.
5. Repeat for the desired number of repetitions.', '0762');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0763', 'Smith reverse calf raises', 'Smith reverse calf raises', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'hamstrings', '', '', 'calves', 'hamstring', '1. Adjust the smith machine bar to a height just below your shoulders.
2. Stand facing the bar with your feet hip-width apart and toes pointing forward.
3. Place the balls of your feet on the edge of a step or platform, with your heels hanging off.
4. Hold onto the bar for support, keeping your back straight and core engaged.
5. Raise your heels as high as possible, lifting your body weight onto the balls of your feet.
6. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
7. Repeat for the desired number of repetitions.', '0763');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1394', 'Smith reverse calf raises', 'Smith reverse calf raises', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'hamstrings', '', '', 'calves', 'hamstring', '1. Adjust the smith machine bar to a height just below your shoulders.
2. Stand facing the bar with your feet hip-width apart and toes pointing forward.
3. Place the balls of your feet on the edge of a step or platform, with your heels hanging off.
4. Hold onto the bar for support.
5. Raise your heels as high as possible, lifting your body up onto your toes.
6. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
7. Repeat for the desired number of repetitions.', '1394');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1361', 'Smith reverse grip bent over row', 'Smith reverse grip bent over row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'upper back', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Set up the smith machine with the bar at hip height.
2. Stand facing the bar with your feet shoulder-width apart.
3. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
4. Grasp the bar with an underhand grip, hands shoulder-width apart.
5. Pull the bar towards your lower chest, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly lower the bar back down to the starting position.
7. Repeat for the desired number of repetitions.', '1361');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0764', 'Smith reverse-grip press', 'Smith reverse-grip press', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Adjust the height of the smith machine bar to chest level.
2. Stand facing the bar with your feet shoulder-width apart.
3. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.
4. Step back and position yourself with a slight bend in your knees.
5. Keep your chest up and core engaged throughout the exercise.
6. Lower the bar towards your chest, keeping your elbows tucked in.
7. Pause for a moment at the bottom, then push the bar back up to the starting position.
8. Repeat for the desired number of repetitions.', '0764');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1395', 'Smith seated one leg calf raise', 'Smith seated one leg calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'hamstrings', '', '', 'calves', 'hamstring', '1. Sit on the machine with your back against the pad and your feet on the footrest.
2. Place one leg on the footrest and keep the other leg off the footrest.
3. Using your calf muscles, raise your heel as high as possible.
4. Pause for a moment at the top, then slowly lower your heel back down to the starting position.
5. Repeat for the desired number of repetitions, then switch legs and repeat.', '1395');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0765', 'Smith seated shoulder press', 'Smith seated shoulder press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Adjust the seat height so that the handles are at shoulder level.
2. Sit on the machine with your back against the pad and your feet flat on the floor.
3. Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.
4. Lower the handles down to shoulder level, keeping your elbows slightly bent.
5. Press the handles up overhead until your arms are fully extended.
6. Pause for a moment at the top, then slowly lower the handles back down to shoulder level.
7. Repeat for the desired number of repetitions.', '0765');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1426', 'Smith seated wrist curl', 'Smith seated wrist curl', 'arms', 'بازو', 'machine', 'دستگاه', 'forearms', 'biceps, brachialis', '', '', 'forearm', 'biceps', '1. Sit on a bench in front of a Smith machine with your feet flat on the ground.
2. Grasp the barbell with an underhand grip, hands shoulder-width apart.
3. Rest your forearms on your thighs, allowing your wrists to hang off.
4. Slowly curl your wrists upward, bringing the barbell towards your forearms.
5. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
6. Repeat for the desired number of repetitions.', '1426');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0766', 'Smith shoulder press', 'Smith shoulder press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.
2. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
3. Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.
4. Press the bar upward until your arms are fully extended overhead.
5. Pause for a moment at the top, then slowly lower the bar back down to shoulder level.
6. Repeat for the desired number of repetitions.', '0766');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0767', 'Smith shrug', 'Smith shrug', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'traps', 'shoulders', '', '', 'trapezius', 'deltoids', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
3. Keep your arms straight and your shoulders relaxed.
4. Lift your shoulders up towards your ears, squeezing your traps at the top.
5. Hold for a moment, then slowly lower your shoulders back down to the starting position.
6. Repeat for the desired number of repetitions.', '0767');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0768', 'Smith single leg split squat', 'Smith single leg split squat', 'legs', 'پا', 'machine', 'دستگاه', 'quads', 'glutes, hamstrings', '', '', 'quadriceps', 'gluteal,hamstring', '1. Stand in front of the smith machine with your feet shoulder-width apart.
2. Place one foot behind you on a bench or step, with your toes pointing forward.
3. Hold onto the smith machine bar for stability.
4. Bend your front knee and lower your body down into a lunge position, keeping your back straight.
5. Pause for a moment at the bottom, then push through your front heel to return to the starting position.
6. Repeat for the desired number of repetitions, then switch legs.', '0768');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0769', 'Smith sprint lunge', 'Smith sprint lunge', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Set up the smith machine with the barbell at hip height.
2. Stand facing away from the machine with your feet shoulder-width apart.
3. Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.
4. Bend your left knee and lower your body into a lunge position, keeping your back straight.
5. Push through your left heel to return to the starting position.
6. Repeat on the other side, stepping back with your left foot.
7. Continue alternating sides for the desired number of repetitions.', '0769');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0770', 'Smith squat', 'Smith squat', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Set up the smith machine with the barbell at an appropriate height for your squat.
2. Stand with your feet shoulder-width apart, toes slightly turned out.
3. Position yourself under the barbell, resting it on your upper traps and shoulders.
4. Grip the barbell with a wide grip, slightly wider than shoulder-width apart.
5. Engage your core and unrack the barbell, stepping back to clear the rack.
6. Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.
7. Lower your body until your thighs are parallel to the ground or slightly below.
8. Pause for a moment at the bottom, then drive through your heels to return to the starting position.
9. Repeat for the desired number of repetitions.', '0770');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0771', 'Smith standing back wrist curl', 'Smith standing back wrist curl', 'arms', 'بازو', 'machine', 'دستگاه', 'forearms', 'biceps, triceps', '', '', 'forearm', 'biceps,triceps', '1. Stand facing the smith machine with your feet shoulder-width apart.
2. Grasp the barbell with an overhand grip, hands shoulder-width apart.
3. Keep your back straight and your elbows close to your body.
4. Slowly curl your wrists upwards, bringing the barbell towards your body.
5. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
6. Repeat for the desired number of repetitions.', '0771');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0772', 'Smith standing behind head military press', 'Smith standing behind head military press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Adjust the seat height of the smith machine so that the bar is at shoulder level.
2. Stand with your feet shoulder-width apart and your knees slightly bent.
3. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
4. Lift the bar off the rack and step back, maintaining a stable stance.
5. Position the bar behind your head, resting on your upper traps.
6. Keep your core engaged and your chest lifted throughout the exercise.
7. Press the bar overhead by extending your arms, fully straightening them.
8. Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.
9. Repeat for the desired number of repetitions.', '0772');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0773', 'Smith standing leg calf raise', 'Smith standing leg calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.
2. Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.
3. Place your hands on the bar for stability.
4. Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.
5. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '0773');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0774', 'Smith standing military press', 'Smith standing military press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
3. Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.
4. Press the barbell upward until your arms are fully extended overhead.
5. Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.
6. Repeat for the desired number of repetitions.', '0774');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3142', 'Smith sumo squat', 'Smith sumo squat', 'legs', 'پا', 'machine', 'دستگاه', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Set up the smith machine with the barbell at hip height.
2. Stand with your feet wider than shoulder-width apart, toes pointing outwards.
3. Position yourself under the barbell, resting it on your upper back and shoulders.
4. Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.
5. Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.
6. Pause for a moment at the bottom, then push through your heels to return to the starting position.
7. Repeat for the desired number of repetitions.', '3142');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1396', 'Smith toe raise', 'Smith toe raise', 'legs', 'پا', 'machine', 'دستگاه', 'calves', 'ankles, shins', '', '', 'calves', 'tibialis', '1. Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.
2. Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.
3. Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.
4. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
5. Engage your core and keep your back straight throughout the exercise.
6. Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.
7. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
8. Repeat for the desired number of repetitions.', '1396');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0775', 'Smith upright row', 'Smith upright row', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'delts', 'traps, biceps', '', '', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart, facing the smith machine.
2. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
3. Keep your back straight and your core engaged.
4. Pull the barbell up towards your chin, leading with your elbows.
5. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
6. Repeat for the desired number of repetitions.', '0775');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1308', 'Smith wide grip bench press', 'Smith wide grip bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Adjust the bench to a comfortable position on the smith machine.
2. Lie down on the bench with your feet flat on the ground.
3. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.
5. Pause for a moment when the barbell touches your chest.
6. Push the barbell back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '1308');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1309', 'Smith wide grip decline bench press', 'Smith wide grip decline bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Adjust the decline bench to the desired angle.
2. Lie down on the bench with your feet secured under the foot pads.
3. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.
5. Pause for a moment when the barbell touches your chest.
6. Push the barbell back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '1309');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0776', 'Snatch pull', 'Snatch pull', 'legs', 'پا', 'barbell', 'هالتر', 'quads', 'hamstrings, glutes, calves', '', '', 'quadriceps', 'hamstring,gluteal,calves', '1. Stand with your feet shoulder-width apart and the barbell on the ground in front of you.
2. Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.
3. Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.
4. As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.
5. As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.
6. Catch the barbell overhead with your arms fully extended and your knees bent.
7. Stand up by extending your hips and knees, keeping the barbell overhead.
8. Lower the barbell back down to the starting position by reversing the movement.
9. Repeat for the desired number of repetitions.', '0776');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0777', 'Spell caster', 'Spell caster', 'core', 'شکم و میان‌تنه', 'dumbbell', 'دمبل', 'abs', 'obliques, lower back', '', '', 'abs', 'obliques,lower-back', '1. Stand with your feet shoulder-width apart and hold a dumbbell in one hand.
2. Bend your knees slightly and hinge forward at the waist, keeping your back straight.
3. Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.
4. Return to the starting position and repeat on the other side.
5. Continue alternating sides for the desired number of repetitions.', '0777');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1362', 'Sphinx', 'Sphinx', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'spine', 'glutes, hamstrings', '', '', 'lower-back', 'gluteal,hamstring', '1. Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.
2. Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.
3. Hold this position for a few seconds, making sure to keep your neck in a neutral position.
4. Slowly lower your chest back down to the starting position.
5. Repeat for the desired number of repetitions.', '1362');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0778', 'Spider crawl push up', 'Spider crawl push up', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'core, chest, shoulders', '', '', 'gluteal', 'abs,chest,deltoids', '1. Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.
2. Bring your right knee towards your right elbow, keeping it off the ground.
3. As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.
4. Push back up to the starting position and repeat with your left knee towards your left elbow.
5. Continue alternating sides for the desired number of repetitions.', '0778');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1363', 'Spine stretch', 'Spine stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'spine', 'hamstrings, glutes', '', '', 'lower-back', 'hamstring,gluteal', '1. Sit on the ground with your legs extended in front of you.
2. Place your hands on the ground behind you, fingers pointing towards your body.
3. Engage your core and slowly lean back, keeping your back straight.
4. Continue leaning back until you feel a stretch in your spine.
5. Hold the stretch for a few seconds, then slowly return to the starting position.
6. Repeat for the desired number of repetitions.', '1363');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2329', 'Spine twist', 'Spine twist', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, lower back', '', '', 'abs', 'obliques,lower-back', '1. Sit on the ground with your legs extended in front of you.
2. Bend your knees and place your feet flat on the ground, hip-width apart.
3. Place your hands behind your head with your elbows pointing outwards.
4. Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.
5. Pause for a moment at the end of the twist, then slowly return to the starting position.
6. Repeat the twist to the left side, bringing your left elbow towards your right knee.
7. Continue alternating sides for the desired number of repetitions.', '2329');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2368', 'Split squats', 'Split squats', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'quads', 'glutes, hamstrings, calves', '', '', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand with your feet shoulder-width apart.
2. Take a step forward with one foot and place it about two feet in front of the other foot.
3. Lower your body by bending your knees and hips, keeping your back straight.
4. Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.
5. Pause for a moment, then push through your front heel to return to the starting position.
6. Repeat for the desired number of repetitions, then switch legs and repeat.', '2368');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0786', 'Squat jerk', 'Squat jerk', 'legs', 'پا', 'barbell', 'هالتر', 'quads', 'glutes, hamstrings, calves, core', '', '', 'quadriceps', 'gluteal,hamstring,calves,abs', '1. Start with the barbell resting on your shoulders, with your feet shoulder-width apart.
2. Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.
3. As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.
4. As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.
5. Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.
6. Stand up from the split position, bringing your feet back together.
7. Lower the barbell back to your shoulders and repeat for the desired number of repetitions.', '0786');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1705', 'Squat on bosu ball', 'Squat on bosu ball', 'legs', 'پا', 'other', 'سایر', 'quads', 'glutes, hamstrings, calves', '', '', 'quadriceps', 'gluteal,hamstring,calves', '1. Place the bosu ball on the ground with the flat side up.
2. Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.
3. Lower your body down by bending your knees and hips, as if sitting back into a chair.
4. Keep your chest up and your weight on your heels.
5. Lower yourself until your thighs are parallel to the ground.
6. Pause for a moment, then push through your heels to return to the starting position.
7. Repeat for the desired number of repetitions.', '1705');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1685', 'Squat to overhead reach', 'Squat to overhead reach', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'quads', 'glutes, hamstrings, core', '', '', 'quadriceps', 'gluteal,hamstring,abs', '1. Stand with your feet shoulder-width apart and toes slightly turned out.
2. Lower your body down into a squat position by bending your knees and pushing your hips back.
3. As you come up from the squat, extend your arms overhead, reaching towards the ceiling.
4. Return to the starting position by lowering your arms and bending your knees to squat down again.
5. Repeat for the desired number of repetitions.', '1685');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1686', 'Squat to overhead reach with twist', 'Squat to overhead reach with twist', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'quads', 'glutes, hamstrings, core', '', '', 'quadriceps', 'gluteal,hamstring,abs', '1. Stand with your feet shoulder-width apart and toes slightly turned out.
2. Lower your body into a squat position by bending your knees and pushing your hips back.
3. As you come up from the squat, raise your arms overhead and twist your torso to one side.
4. Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.
5. Continue alternating sides with each squat repetition.', '1686');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2297', 'Stability ball crunch (full range hands behind head)', 'Stability ball crunch (full range hands behind head)', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.
4. Pause for a moment at the top, then slowly lower your upper body back to the starting position.
5. Repeat for the desired number of repetitions.', '2297');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3291', 'Stalder press', 'Stalder press', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'shoulders, core', '', '', 'triceps', 'deltoids,abs', '1. Start by standing with your feet shoulder-width apart and your arms extended overhead.
2. Bend your knees slightly and engage your core.
3. Lower your body down into a squat position while keeping your arms extended overhead.
4. As you squat down, press your arms down towards the ground, engaging your triceps.
5. Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.
6. Repeat for the desired number of repetitions.', '3291');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3669', 'Standing archer', 'Standing archer', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'upper back', 'shoulders, biceps, forearms', '', '', 'upper-back', 'deltoids,biceps,forearm', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Extend your arms straight out in front of you at shoulder height, parallel to the ground.
3. Rotate your torso to the right, keeping your arms extended and your back straight.
4. As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.
5. Hold the position for a moment, then return to the starting position.
6. Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.
7. Continue alternating sides for the desired number of repetitions.', '3669');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0788', 'Standing behind neck press', 'Standing behind neck press', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.
2. Keep your back straight and core engaged.
3. Press the barbell overhead by extending your arms, fully extending your elbows.
4. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0788');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1490', 'Standing calf raise (on a staircase)', 'Standing calf raise (on a staircase)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'calves', 'ankles, feet', '', '', 'calves', '', '1. Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.
2. Hold onto a railing or wall for balance if needed.
3. Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.
4. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
5. Repeat for the desired number of repetitions.', '1490');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1397', 'Standing calves', 'Standing calves', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Stand with your feet shoulder-width apart, toes pointing forward.
2. Raise your heels off the ground as high as possible, standing on your toes.
3. Hold the position for a moment, then slowly lower your heels back down to the starting position.
4. Repeat for the desired number of repetitions.', '1397');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1398', 'Standing calves calf stretch', 'Standing calves calf stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Stand facing a wall or sturdy object, about an arm''s length away.
2. Place your hands on the wall or object at shoulder height.
3. Step back with one foot, keeping your heel flat on the ground.
4. Bend your front knee slightly and lean forward, keeping your back leg straight.
5. You should feel a stretch in your calf muscle.
6. Hold the stretch for 20-30 seconds.
7. Repeat on the other leg.', '1398');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1599', 'Standing hamstring and calf stretch with strap', 'Standing hamstring and calf stretch with strap', 'legs', 'پا', 'other', 'سایر', 'hamstrings', 'calves', '', '', 'hamstring', 'calves', '1. Stand upright with your feet shoulder-width apart.
2. Hold the strap with both hands and place it around the ball of your foot.
3. Keep your leg straight and slowly lean forward from your hips, keeping your back straight.
4. Feel the stretch in your hamstring and calf muscles.
5. Hold the stretch for 20-30 seconds.
6. Release the stretch and repeat with the other leg.
7. Repeat for the desired number of repetitions.', '1599');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0794', 'Standing lateral stretch', 'Standing lateral stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'shoulders, obliques', '', '', 'upper-back', 'deltoids,obliques', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Extend your arms straight out to the sides, parallel to the ground.
3. Slowly lean your upper body to one side, feeling a stretch in your side and lats.
4. Hold the stretch for 15-30 seconds.
5. Return to the starting position and repeat on the other side.
6. Repeat for the desired number of repetitions.', '0794');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1364', 'Standing pelvic tilt', 'Standing pelvic tilt', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'spine', 'abdominals', '', '', 'lower-back', 'abs', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Place your hands on your hips or let them hang by your sides.
3. Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.
4. Hold the position for a few seconds, then release and return to the starting position.
5. Repeat for the desired number of repetitions.', '1364');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0795', 'Standing single leg curl', 'Standing single leg curl', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'hamstrings', 'glutes', '', '', 'hamstring', 'gluteal', '1. Stand with your feet hip-width apart and your hands on your hips.
2. Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.
3. Slowly curl your right heel towards your glutes, squeezing your hamstring.
4. Pause for a moment at the top, then slowly lower your right foot back down to the starting position.
5. Repeat for the desired number of repetitions, then switch legs.', '0795');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0796', 'Standing wheel rollerout', 'Standing wheel rollerout', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'abs', 'lower back, shoulders', '', '', 'abs', 'lower-back,deltoids', '1. Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.
2. Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.
3. Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.
4. Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.
5. Repeat for the desired number of repetitions.', '0796');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3314', 'Straddle maltese', 'Straddle maltese', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'shoulders, chest', '', '', 'abs', 'deltoids,chest', '1. Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.
2. Spread your legs wide apart, forming a straddle position.
3. Engage your core and slowly lower your body until your arms are parallel to the ground.
4. Hold this position for a few seconds, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '3314');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3298', 'Straddle planche', 'Straddle planche', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'shoulders, triceps, chest', '', '', 'abs', 'deltoids,triceps,chest', '1. Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.
2. Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.
3. Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.
4. Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.
5. Repeat for the desired number of repetitions.', '3298');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1427', 'Straight leg outer hip abductor', 'Straight leg outer hip abductor', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'abductors', 'glutes, hamstrings', '', '', 'gluteal', 'hamstring', '1. Lie on your side with your legs straight and stacked on top of each other.
2. Place your bottom arm under your head for support.
3. Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.
4. Pause for a moment at the top, then slowly lower your leg back down to the starting position.
5. Repeat for the desired number of repetitions, then switch sides.', '1427');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0803', 'Superman push-up', 'Superman push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'core, shoulders', '', '', 'chest', 'abs,deltoids', '1. Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.
2. Engage your core and lower your body towards the ground, keeping your elbows close to your sides.
3. As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.
4. Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.
5. Repeat the movement, this time lifting your left arm and right leg.
6. Continue alternating sides for the desired number of repetitions.', '0803');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0805', 'Suspended abdominal fallout', 'Suspended abdominal fallout', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, hip flexors', '', '', 'abs', 'obliques,hip-flexors', '1. Attach a suspension trainer to a high anchor point and adjust the straps to waist height.
2. Stand facing away from the anchor point and hold the handles with your arms extended in front of you.
3. Lean forward at the waist, keeping your body straight and your core engaged.
4. Lower your body as far as you can while maintaining control and tension in your abs.
5. Pause for a moment at the bottom, then slowly raise your body back up to the starting position.
6. Repeat for the desired number of repetitions.', '0805');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0806', 'Suspended push-up', 'Suspended push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders, core', '', '', 'chest', 'triceps,deltoids,abs', '1. Find a suspension trainer and adjust it to an appropriate height.
2. Stand facing away from the anchor point and hold the handles with an overhand grip.
3. Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.
4. Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.
5. Push through your chest and arms to return to the starting position.
6. Repeat for the desired number of repetitions.', '0806');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0807', 'Suspended reverse crunch', 'Suspended reverse crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.
3. Pause for a moment at the top, then slowly lower your knees back down to the starting position.
4. Repeat for the desired number of repetitions.', '0807');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0808', 'Suspended row', 'Suspended row', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'upper back', 'biceps, shoulders', '', '', 'upper-back', 'biceps,deltoids', '1. Set up a suspension trainer at an appropriate height.
2. Stand facing the anchor point with your feet shoulder-width apart.
3. Hold the handles with an overhand grip, palms facing each other.
4. Lean back, keeping your body straight and your heels on the ground.
5. Pull your chest towards the handles, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly lower yourself back to the starting position.
7. Repeat for the desired number of repetitions.', '0808');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0809', 'Suspended split squat', 'Suspended split squat', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'quads', 'glutes, hamstrings, calves', '', '', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand facing away from a suspension trainer with your feet shoulder-width apart.
2. Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.
3. Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.
4. Push through your heel to return to the starting position.
5. Repeat for the desired number of repetitions, then switch legs.', '0809');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3433', 'Swimmer kicks v. 2 (male)', 'Swimmer kicks v. 2 (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'hamstrings, quadriceps, calves', '', '', 'gluteal', 'hamstring,quadriceps,calves', '1. Lie face down on a mat with your arms extended overhead.
2. Engage your core and lift your chest and legs off the ground simultaneously.
3. Kick your legs up and down in a fluttering motion, as if you were swimming.
4. Continue kicking for the desired number of repetitions.
5. Lower your chest and legs back down to the starting position.', '3433');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1753', 'Three bench dip', 'Three bench dip', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Sit on a bench with your hands gripping the edge, fingers pointing forward.
2. Slide your butt off the bench, supporting your weight with your hands.
3. Bend your elbows and lower your body until your upper arms are parallel to the ground.
4. Push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '1753');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2459', 'Tire flip', 'Tire flip', 'legs', 'پا', 'other', 'سایر', 'glutes', 'hamstrings, quadriceps, core', '', '', 'gluteal', 'hamstring,quadriceps,abs', '1. Stand with your feet shoulder-width apart, facing the tire.
2. Bend your knees and hinge at the hips, lowering into a squat position.
3. Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.
4. Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.
5. As the tire flips over, use your upper body strength to guide it and maintain control.
6. Once the tire is fully flipped, quickly step back and reset your stance.
7. Repeat for the desired number of repetitions.', '2459');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0811', 'Trap bar deadlift', 'Trap bar deadlift', 'legs', 'پا', 'other', 'سایر', 'glutes', 'hamstrings, quadriceps, lower back', '', '', 'gluteal', 'hamstring,quadriceps,lower-back', '1. Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.
2. Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.
3. Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.
4. As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.
5. Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.
6. Repeat for the desired number of repetitions.', '0811');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0814', 'Triceps dip', 'Triceps dip', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.
2. Slide your butt off the bench, supporting your weight with your hands.
3. Bend your elbows and lower your body towards the ground, keeping your back close to the bench.
4. Pause for a moment at the bottom, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '0814');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0812', 'Triceps dip (bench leg)', 'Triceps dip (bench leg)', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.
2. Walk your feet forward, sliding your butt off the bench, and straighten your arms.
3. Bend your elbows and lower your body towards the ground, keeping your back close to the bench.
4. Push through your palms to straighten your arms and return to the starting position.
5. Repeat for the desired number of repetitions.', '0812');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0813', 'Triceps dip (between benches)', 'Triceps dip (between benches)', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.
2. Slide your butt off the bench, supporting your weight with your hands.
3. Bend your elbows and lower your body towards the ground, keeping your back close to the bench.
4. Pause for a moment at the bottom, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '0813');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0815', 'Triceps dips floor', 'Triceps dips floor', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.
2. Slide your butt off the front of the chair with your legs extended in front of you.
3. Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.
4. Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.
5. Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.
6. Repeat for the desired number of repetitions.', '0815');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0816', 'Triceps press', 'Triceps press', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Extend your arms straight out in front of you, parallel to the ground.
3. Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.
4. Pause for a moment at the bottom, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '0816');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0817', 'Triceps stretch', 'Triceps stretch', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'shoulders', '', '', 'triceps', 'deltoids', '1. Stand or sit upright with your back straight.
2. Extend one arm overhead, bending it at the elbow.
3. Place your opposite hand on the bent elbow and gently pull it towards your head.
4. Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.
5. Release the stretch and repeat on the other arm.', '0817');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0871', 'Tuck crunch', 'Tuck crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.
4. Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.
5. Repeat for the desired number of repetitions.', '0871');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0818', 'Twin handle parallel grip lat pulldown', 'Twin handle parallel grip lat pulldown', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'lats', 'biceps, rhomboids, rear deltoids', '', '', 'upper-back', 'biceps,deltoids', '1. Adjust the seat height and position yourself facing the cable machine.
2. Grasp the handles with an overhand grip, hands shoulder-width apart.
3. Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.
4. Lean back slightly and keep your chest up, maintaining a neutral spine.
5. Pull the handles down towards your upper chest, squeezing your shoulder blades together.
6. Pause for a moment at the bottom of the movement, feeling the contraction in your lats.
7. Slowly release the handles and return to the starting position.
8. Repeat for the desired number of repetitions.', '0818');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1466', 'Twist hip lift', 'Twist hip lift', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'obliques, hamstrings', '', '', 'gluteal', 'obliques,hamstring', '1. Lie on your back with your knees bent and feet flat on the ground.
2. Place your hands by your sides for support.
3. Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.
4. While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.
5. Return to the starting position and repeat the twist to the left side.
6. Continue alternating twists for the desired number of repetitions.', '1466');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2802', 'Twisted leg raise', 'Twisted leg raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, hip flexors', '', '', 'abs', 'obliques,hip-flexors', '1. Lie flat on your back with your legs extended and your arms by your sides.
2. Place your hands under your glutes for support.
3. Engage your abs and lift both legs off the ground, keeping them straight.
4. As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.
5. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
6. Repeat the movement, this time twisting your hips to the other side.
7. Continue alternating sides for the desired number of repetitions.', '2802');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2801', 'Twisted leg raise (female)', 'Twisted leg raise (female)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, hip flexors', '', '', 'abs', 'obliques,hip-flexors', '1. Lie flat on your back with your legs extended and your arms by your sides.
2. Bend your knees and lift your legs off the ground, bringing them towards your chest.
3. As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat the movement, this time twisting your hips to the other side.
6. Continue alternating sides for the desired number of repetitions.', '2801');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3231', 'Two toe touch (male)', 'Two toe touch (male)', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'spine', 'hamstrings, glutes', '', '', 'lower-back', 'hamstring,gluteal', '1. Stand with your feet shoulder-width apart and your arms extended out to the sides.
2. Bend forward at the waist, keeping your back straight and your knees slightly bent.
3. Reach down towards your toes with both hands, keeping your legs straight.
4. Pause for a moment at the bottom, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '3231');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1365', 'Upper back stretch', 'Upper back stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'upper back', 'shoulders', '', '', 'upper-back', 'deltoids', '1. Stand up straight with your feet shoulder-width apart.
2. Extend your arms straight in front of you, parallel to the ground.
3. Interlace your fingers and rotate your palms away from your body.
4. Slowly raise your arms overhead, keeping them straight and parallel to each other.
5. As you raise your arms, squeeze your shoulder blades together.
6. Hold the stretch for 15-30 seconds, then release and repeat.', '1365');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1366', 'Upward facing dog', 'Upward facing dog', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'spine', 'shoulders, chest', '', '', 'lower-back', 'deltoids,chest', '1. Lie face down on the floor with your legs extended behind you.
2. Place your hands on the floor next to your lower ribs, fingers pointing forward.
3. Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.
4. Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.
5. Hold this position for a few breaths, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '1366');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3420', 'V-sit on floor', 'V-sit on floor', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Sit on the floor with your legs extended in front of you.
2. Lean back slightly and lift your legs off the ground, keeping them straight.
3. Simultaneously, lift your upper body off the ground and reach your arms towards your legs.
4. Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '3420');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0826', 'Vertical leg raise (on parallel bars)', 'Vertical leg raise (on parallel bars)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors', '', '', 'abs', 'hip-flexors', '1. Hang from the parallel bars with your arms fully extended and your body straight.
2. Engage your core and lift your legs up in front of you, keeping them straight.
3. Continue lifting until your legs are parallel to the ground or slightly higher.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0826');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1460', 'Walking lunge', 'Walking lunge', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart.
2. Take a step forward with your right leg, lowering your body into a lunge position.
3. Keep your torso upright and your front knee aligned with your ankle.
4. Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.
5. Continue alternating legs and walking forward, maintaining a controlled and steady pace.
6. Repeat for the desired number of repetitions.', '1460');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0830', 'Weighted bench dip', 'Weighted bench dip', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Sit on a bench with your hands gripping the edge, fingers pointing forward.
2. Slide your butt off the bench, supporting your weight with your hands.
3. Lower your body by bending your elbows until your upper arms are parallel to the floor.
4. Push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '0830');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2987', 'Weighted close grip chin-up on dip cage', 'Weighted close grip chin-up on dip cage', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.
2. Hang from the bars with your arms fully extended, feet off the ground, and body straight.
3. Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.
4. Continue pulling until your chin is above the bars, then pause for a moment.
5. Slowly lower your body back down to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '2987');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3643', 'Weighted cossack squats (male)', 'Weighted cossack squats (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.
2. Hold a weight in front of your chest with both hands.
3. Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.
4. Go as low as you can while maintaining balance and keeping your chest up.
5. Push through the heel of the bent leg to return to the starting position.
6. Repeat on the other side, alternating between legs.', '3643');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0832', 'Weighted crunch', 'Weighted crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques', '', '', 'abs', 'obliques', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Hold a weight plate or dumbbell on your chest.
3. Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0832');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3670', 'Weighted decline sit-up', 'Weighted decline sit-up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors, lower back', '', '', 'abs', 'hip-flexors,lower-back', '1. Lie flat on a decline bench with your feet secured under the foot pads.
2. Place your hands behind your head or across your chest.
3. Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '3670');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0833', 'Weighted donkey calf raise', 'Weighted donkey calf raise', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'calves', 'hamstrings, glutes', '', '', 'calves', 'hamstring,gluteal', '1. Stand on a raised platform with your toes on the edge and your heels hanging off.
2. Hold onto a stable object for support.
3. Raise your heels as high as possible by extending your ankles.
4. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
5. Repeat for the desired number of repetitions.', '0833');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1310', 'Weighted drop push up', 'Weighted drop push up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.
2. Lower your chest towards the ground, keeping your elbows close to your body.
3. Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.
4. As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.
5. Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.
6. Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.
7. Continue alternating between the wider and narrower hand positions for the desired number of repetitions.', '1310');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2135', 'Weighted front plank', 'Weighted front plank', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'shoulders, lower back', '', '', 'abs', 'deltoids,lower-back', '1. Start by lying face down on the floor.
2. Place your forearms on the ground, with your elbows directly under your shoulders.
3. Extend your legs straight out behind you, with your toes on the ground.
4. Engage your core and lift your body off the ground, balancing on your forearms and toes.
5. Keep your body in a straight line from your head to your heels.
6. Hold this position for the desired amount of time.
7. Lower your body back down to the starting position.
8. Repeat for the desired number of repetitions.', '2135');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0834', 'Weighted front raise', 'Weighted front raise', 'shoulders', 'سرشانه', 'bodyweight', 'وزن بدن', 'delts', 'biceps, forearms', '', '', 'deltoids', 'biceps,forearm', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.
2. Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.
3. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.
4. Repeat for the desired number of repetitions.', '0834');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0866', 'Weighted hanging leg-hip raise', 'Weighted hanging leg-hip raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'hip flexors, lower back', '', '', 'abs', 'hip-flexors,lower-back', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core and lift your legs up in front of you, keeping them straight.
3. Continue lifting until your legs are parallel to the ground or slightly higher.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0866');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0835', 'Weighted hyperextension (on stability ball)', 'Weighted hyperextension (on stability ball)', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'spine', 'glutes, hamstrings', '', '', 'lower-back', 'gluteal,hamstring', '1. Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.
2. Place your hands behind your head or cross them over your chest.
3. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0835');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3641', 'Weighted kneeling step with swing', 'Weighted kneeling step with swing', 'shoulders', 'سرشانه', 'bodyweight', 'وزن بدن', 'delts', 'triceps, core', '', '', 'deltoids', 'triceps,abs', '1. Start in a kneeling position with your knees hip-width apart and your back straight.
2. Hold a weight in each hand, with your arms extended straight down in front of you.
3. Engage your core and swing the weights up and overhead, keeping your arms straight.
4. Lower the weights back down to the starting position and repeat for the desired number of repetitions.', '3641');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3644', 'Weighted lunge with swing', 'Weighted lunge with swing', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a weight in each hand.
2. Take a step forward with your right foot, lowering your body into a lunge position.
3. As you lunge forward, swing the weights forward and upward, keeping your arms straight.
4. Push off with your right foot and return to the starting position, swinging the weights back down.
5. Repeat with your left foot and continue alternating legs for the desired number of repetitions.', '3644');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3286', 'Weighted muscle up', 'Weighted muscle up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, triceps, shoulders, chest', '', '', 'upper-back', 'biceps,triceps,deltoids,chest', '1. Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.
2. Engage your core and pull your body up towards the bar, leading with your chest.
3. As you reach the top of the movement, transition your grip so that your palms are facing towards you.
4. Continue pulling yourself up until your chest reaches the bar, then pause for a moment.
5. Slowly lower yourself back down to the starting position, maintaining control throughout the movement.
6. Repeat for the desired number of repetitions.', '3286');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3312', 'Weighted muscle up (on bar)', 'Weighted muscle up (on bar)', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, triceps, shoulders, forearms', '', '', 'upper-back', 'biceps,triceps,deltoids,forearm', '1. Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.
2. Engage your core and pull your shoulder blades down and back.
3. Bend your elbows and pull your chest towards the bar, keeping your body straight.
4. Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.
5. Pause at the top of the movement, then slowly lower yourself back down to the starting position.
6. Repeat for the desired number of repetitions.', '3312');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3290', 'Weighted one hand pull up', 'Weighted one hand pull up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.
2. Hang from the bar with your arm fully extended and your body straight.
3. Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.
4. Continue pulling until your chin is above the bar.
5. Lower your body back down to the starting position with control.
6. Repeat for the desired number of repetitions.', '3290');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0840', 'Weighted overhead crunch (on stability ball)', 'Weighted overhead crunch (on stability ball)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, lower back', '', '', 'abs', 'obliques,lower-back', '1. Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Hold a weight plate or dumbbell with both hands and extend your arms overhead.
3. Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.
4. Pause for a moment at the top, then slowly lower your torso back to the starting position.
5. Repeat for the desired number of repetitions.', '0840');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0841', 'Weighted pull-up', 'Weighted pull-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.
2. Hang from the bar with your arms fully extended and your body straight.
3. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.
4. Continue pulling until your chin is above the bar.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '0841');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0844', 'Weighted round arm', 'Weighted round arm', 'shoulders', 'سرشانه', 'bodyweight', 'وزن بدن', 'delts', 'triceps, upper back', '', '', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Raise your arms out to the sides, keeping a slight bend in your elbows.
4. Continue lifting your arms until they are parallel to the ground.
5. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
6. Repeat for the desired number of repetitions.', '0844');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0846', 'Weighted russian twist', 'Weighted russian twist', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, lower back', '', '', 'abs', 'obliques,lower-back', '1. Sit on the ground with your knees bent and your feet flat on the floor.
2. Hold a weight or medicine ball with both hands in front of your chest.
3. Lean back slightly, keeping your back straight and your core engaged.
4. Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.
5. Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.
6. Continue alternating sides for the desired number of repetitions.', '0846');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0845', 'Weighted russian twist (legs up)', 'Weighted russian twist (legs up)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, hip flexors', '', '', 'abs', 'obliques,hip-flexors', '1. Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.
2. Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.
3. Lean back slightly to engage your core muscles.
4. Twist your torso to the right, bringing the weight towards the ground on your right side.
5. Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.
6. Continue alternating sides for the desired number of repetitions.', '0845');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2371', 'Weighted russian twist v. 2', 'Weighted russian twist v. 2', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, lower back', '', '', 'abs', 'obliques,lower-back', '1. Sit on the ground with your knees bent and feet flat on the floor.
2. Hold the weight with both hands in front of your chest.
3. Lean back slightly to engage your core muscles.
4. Twist your torso to the right, bringing the weight towards the right side of your body.
5. Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.
6. Continue alternating sides for the desired number of repetitions.', '2371');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0847', 'Weighted seated bicep curl (on stability ball)', 'Weighted seated bicep curl (on stability ball)', 'arms', 'بازو', 'other', 'سایر', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Sit on a stability ball with your feet flat on the ground and your back straight.
2. Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.
3. Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.
4. Pause for a moment at the top, squeezing your biceps.
5. Inhale and slowly lower the medicine ball back down to the starting position.
6. Repeat for the desired number of repetitions.', '0847');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0849', 'Weighted seated twist (on stability ball)', 'Weighted seated twist (on stability ball)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, lower back', '', '', 'abs', 'obliques,lower-back', '1. Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Hold a weight plate or dumbbell with both hands close to your chest.
3. Engage your core and slowly rotate your torso to one side, keeping your hips stable.
4. Pause for a moment at the end of the rotation, then slowly return to the starting position.
5. Repeat the rotation to the other side.
6. Continue alternating sides for the desired number of repetitions.', '0849');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0850', 'Weighted side bend (on stability ball)', 'Weighted side bend (on stability ball)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'obliques, lower back', '', '', 'abs', 'obliques,lower-back', '1. Sit on a stability ball with your feet shoulder-width apart and flat on the ground.
2. Hold a weight in one hand and place your other hand on your hip.
3. Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.
4. Pause for a moment at the bottom, then slowly return to the starting position.
5. Repeat for the desired number of repetitions, then switch sides.', '0850');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0851', 'Weighted sissy squat', 'Weighted sissy squat', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'quads', 'glutes, hamstrings, calves', '', '', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand with your feet shoulder-width apart and your toes pointing slightly outward.
2. Hold a weight in front of your chest with both hands, or place a barbell across your upper back.
3. Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips.
4. Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go.
5. Pause for a moment at the bottom, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '0851');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0852', 'Weighted squat', 'Weighted squat', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, toes pointing slightly outward.
2. Hold a weight in front of your chest or on your shoulders.
3. Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.
4. Lower until your thighs are parallel to the ground, or as low as you can comfortably go.
5. Push through your heels to stand back up, squeezing your glutes at the top.
6. Repeat for the desired number of repetitions.', '0852');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0853', 'Weighted standing curl', 'Weighted standing curl', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'biceps', 'forearms', '', '', 'biceps', 'forearm', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.
2. Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.
3. Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.
4. Repeat for the desired number of repetitions.', '0853');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0854', 'Weighted standing hand squeeze', 'Weighted standing hand squeeze', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'forearms', 'biceps, triceps', '', '', 'forearm', 'biceps,triceps', '1. Stand with your feet shoulder-width apart and hold a weight in each hand.
2. Extend your arms straight in front of you, palms facing each other.
3. Squeeze your hands together as hard as you can, engaging your forearms.
4. Hold the squeeze for a few seconds, then release.
5. Repeat for the desired number of repetitions.', '0854');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3313', 'Weighted straight bar dip', 'Weighted straight bar dip', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Position yourself between parallel bars with your arms fully extended and your body straight.
2. Lower your body by bending your elbows until your upper arms are parallel to the ground.
3. Pause for a moment, then push yourself back up to the starting position by straightening your arms.
4. Repeat for the desired number of repetitions.', '3313');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3642', 'Weighted stretch lunge', 'Weighted stretch lunge', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'glutes', 'quadriceps, hamstrings, calves', '', '', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart.
2. Take a step forward with your right foot, keeping your back straight.
3. Lower your body by bending your knees until your right thigh is parallel to the ground.
4. Push through your right heel to return to the starting position.
5. Repeat with your left leg.
6. Continue alternating legs for the desired number of repetitions.', '3642');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0856', 'Weighted svend press', 'Weighted svend press', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'shoulders, triceps', '', '', 'chest', 'deltoids,triceps', '1. Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.
2. Keep your elbows slightly bent and your palms facing each other.
3. Press the weight plate straight out in front of you, fully extending your arms.
4. Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.
5. Repeat for the desired number of repetitions.', '0856');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1754', 'Weighted three bench dips', 'Weighted three bench dips', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.
2. Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.
3. Lower your body by bending your elbows, keeping your back close to the bench.
4. Pause for a moment at the bottom, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '1754');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1755', 'Weighted tricep dips', 'Weighted tricep dips', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.
2. Slide your butt off the front of the bench with your legs extended in front of you.
3. Keep your back close to the bench and your elbows slightly bent.
4. Lower your body by bending your elbows until your upper arms are parallel to the floor.
5. Push yourself back up to the starting position by straightening your arms.
6. Repeat for the desired number of repetitions.', '1755');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1767', 'Weighted triceps dip on high parallel bars', 'Weighted triceps dip on high parallel bars', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'triceps', 'chest, shoulders', '', '', 'triceps', 'chest,deltoids', '1. Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.
2. Bend your elbows and lower your body until your upper arms are parallel to the ground.
3. Pause for a moment, then push through your palms to straighten your arms and return to the starting position.
4. Repeat for the desired number of repetitions.', '1767');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0857', 'Wheel rollerout', 'Wheel rollerout', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'abs', 'lower back', '', '', 'abs', 'lower-back', '1. Kneel on the floor and place the wheel roller in front of you.
2. Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.
3. Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.
4. Continue rolling forward until your body is fully extended and your arms are overhead.
5. Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.
6. Repeat for the desired number of repetitions.', '0857');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1429', 'Wide grip pull-up', 'Wide grip pull-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.
2. Engage your core and squeeze your shoulder blades together.
3. Pull your body up towards the bar until your chin is above the bar.
4. Lower your body back down to the starting position with control.
5. Repeat for the desired number of repetitions.', '1429');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1367', 'Wide grip rear pull-up', 'Wide grip rear pull-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'lats', 'biceps, forearms', '', '', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.
2. Hang from the bar with your arms fully extended and your body straight.
3. Engage your back muscles and pull your body up towards the bar, leading with your chest.
4. Continue pulling until your chin is above the bar.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '1367');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1311', 'Wide hand push up', 'Wide hand push up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Start in a high plank position with your hands wider than shoulder-width apart.
2. Keep your body in a straight line from head to toe.
3. Lower your chest towards the ground by bending your elbows, keeping them close to your sides.
4. Push through your palms to extend your arms and return to the starting position.
5. Repeat for the desired number of repetitions.', '1311');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2363', 'Wide-grip chest dip on high parallel bars', 'Wide-grip chest dip on high parallel bars', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'pectorals', 'triceps, shoulders', '', '', 'chest', 'triceps,deltoids', '1. Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.
2. Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.
3. Pause for a moment, then push yourself back up to the starting position by straightening your arms.
4. Repeat for the desired number of repetitions.', '2363');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0858', 'Wind sprints', 'Wind sprints', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'abs', 'quadriceps, hamstrings, calves', '', '', 'abs', 'quadriceps,hamstring,calves', '1. Find an open space or a track to perform the exercise.
2. Start by standing with your feet shoulder-width apart.
3. Begin running as fast as you can, pumping your arms and driving your knees up.
4. Continue sprinting for a specific distance or time period.
5. Rest and repeat for the desired number of repetitions.', '0858');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1604', 'World greatest stretch', 'World greatest stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'hamstrings', 'glutes, quadriceps, calves', '', '', 'hamstring', 'gluteal,quadriceps,calves', '1. Start in a lunge position with your right foot forward and your left foot back.
2. Place your hands on the ground on either side of your right foot.
3. Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.
4. Rotate your torso to the right, reaching your right arm up towards the ceiling.
5. Hold this position for a few seconds, then return to the starting position.
6. Switch sides and repeat the stretch with your left foot forward.', '1604');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1428', 'Wrist circles', 'Wrist circles', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'forearms', 'hands, wrists', '', '', 'forearm', '', '1. Extend your arms straight out in front of you.
2. Make a fist with both hands.
3. Rotate your wrists in a circular motion, keeping your arms still.
4. Continue the wrist circles for the desired number of repetitions.', '1428');
INSERT OR IGNORE INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0859', 'Wrist rollerer', 'Wrist rollerer', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'forearms', 'biceps, triceps', '', '', 'forearm', 'biceps,triceps', '1. Attach a weight to one end of a rope or bar.
2. Hold the other end of the rope or bar with both hands, palms facing down.
3. Stand with your feet shoulder-width apart and your arms fully extended in front of you.
4. Slowly roll the weight up towards your hands by flexing your wrists.
5. Pause for a moment at the top, then slowly lower the weight back down to the starting position.
6. Repeat for the desired number of repetitions.', '0859');
